comms.text:
@1 וְצַלֵיתִי קֳדָם יְיָ בְּעִדָנָא הַהִיא לְמֵימָר:
@2 יְיָ אֱלֹהִים אַתְּ שָׁרֵיתָא לְאַחֲזָאָה יָת עַבְדָךְ יָת רְבוּתָךְ וְיָת יְדָךְ תַּקֶפְתָּא דִי אַתְּ הוּא אֱלָהָא דִשְׁכִנְתָּךְ בִּשְׁמַיָא מִלְעֵלָא וְשַׁלִיט בְּאַרְעָא וְלֵית דְיַעְבֵּד כְּעוֹבְדָיךְ וּכְגִבָּרְתָּךְ:
@3 אֵעִבַר כְּעַן וְאֶחֱזֵי יָת אַרְעָא טַבְתָא דִּי בְּעִבְרָא דְיַרְדְנָא טוּרָא טָּבָא הָדֵין וּבֵית מַקְדָשָׁא:
@4 וַהֲוָה רְגַז מִן קֳדָם יְיָ עֲלַי בְּדִילְכוֹן וְלָא קַבִּיל מִנִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסֵף לְמַלָלָא קֳדָמַי עוֹד בְּפִתְגָמָא הָדֵין:
@5 סַק לְרֵישׁ רָמָתָא וּזְקוֹף עֵינָיךְ לְמַעֲרָבָא וּלְצִפּוּנָא וְלִדְרוֹמָא וּלְמָדִינְחָא וַחֲזֵי בְעֵינָיךְ אֲרֵי לָא תְעִבַר יָת יַרְדְנָא הָדֵין:
@6 וּפַקֵד יָת יְהוֹשֻׁעַ וְתַקֶפְהִי וְאַלֶמְהִי אֲרֵי הוּא יֵעִבַר קֳדָם עַמָא הָדֵין וְהוּא יַחְסֵן יָתְהוֹן יָת אַרְעָא דִי תֶחֱזֵי:
@7 וִיתֵבְנָא בְחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר:
@8 וּכְעַן יִשְׂרָאֵל שְׁמַע לִקְיָמַיָא וּלְדִינַיָא דִי אֲנָא מְאַלֵף יָתְכוֹן לְמֶעְבַּד בְּדִיל דְתֵיחוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יָהֵב לְכוֹן:
@9 לָא תוֹסְפוּן עַל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן וְלָא תִמְנְעוּן מִנֵהּ לְמִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן:
@10 עֵינֵיכוֹן חָזָן יָת דִי עֲבַד יְיָ בְּבַעַל פְּעוֹר אֲרֵי כָּל גַבְרָא דִי אֲזַל בָּתַר בַּעַל פְּעוֹר שֵׁצְיֵהּ יְיָ אֱלָהָךְ מִבֵּינָךְ:
@11 וְאַתּוּן דְאַדְבֶּקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהֲכוֹן קַיָמִין כֻּלְכוֹן יוֹמָא דֵין:
@12 חֲזוֹ דְאַלֵפִית יָתְכוֹן קְיָמַיָא וְדִינַיָא כְּמָא דִי פַקְדַנִי יְיָ אֱלָהָי לְמֶעְבַּד כֵּן בְּגוֹ אַרְעָא דִי אַתּוּן עַלִין תַּמָן לְמֵירְתַהּ:
@13 וְתִטְרוּן וְתַעְבְּדוּן אֲרֵי הִיא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְעֵינֵי עַמְמַיָא דִי יִשְׁמְעוּן יָת כָּל קְיָמַיָא הָאִלֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין:
@14 אֲרֵי מָן עַם רַב דִי לֵהּ אֱלָהָא קָרִיב לֵהּ לְקַבָּלָא צְלוֹתֵהּ בְּעִדַן עַקְתֵהּ כַּייָ אֱלָהָנָא בְּכָל עִדָן דַאֲנַחְנָא מְצַלִין קֳדָמוֹהִי:
@15 וּמָן עַם רַב דִי לֵהּ קְיָמִין וְדִינִין קַשִׁיטִין כְּכֹל אוֹרַיְתָא הָדָא דִי אֲנָא יָהֵב קֳדָמֵכוֹן יוֹמָא דֵין:
@16 לְחוֹד אִסְתַּמַר לָךְ וְטַר נַפְשָׁךְ לַחֲדָא דִילְמָא תִנְשֵׁי יָת פִּתְגָמַיָא דִי חֲזוֹ עֵינָיִךְ וְדִילְמָא יְעִדוּן מִלִבָּךְ כֹּל יוֹמֵי חַיָיךְ וּתְהוֹדְעִנוּן לִבְנָיךְ וְלִבְנֵי בְנָיִךְ:
@17 יוֹמָא דִי קַמְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב כַּד אֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יָת עַמָא וְאַשְׁמְעִנוּן יָת פִּתְגָמָי דִי יֵלְפוּן לְמִדְחַל קֳדָמַי כָּל יוֹמַיָא דִי אִנוּן קַיָמִין עַל אַרְעָא וְיָת בְּנֵיהוֹן יְאַלְפוּן:
@18 וּקְרֶבְתּוּן וְקַמְתּוּן בְּשִׁפּוֹלֵי טוּרָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וַאֲמִיטְתָא:
@19 וּמַלִיל יְיָ עִמְכוֹן מִגוֹ אֶשְׁתָא קַל פִּתְגָמִין אַתּוּן שָׁמְעִין וּדְמוּת לֵיתֵיכוֹן חָזָן אֱלָהֵן קָלָא:
@20 וְחַוִי לְכוֹן יָת קְיָמֵהּ דִי פַקִיד יָתְכוֹן לְמֶעְבַּד עַשְׂרָא פִּתְגָמִין וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא:
@21 וְיָתִי פַּקִיד יְיָ בְּעִדְנָא הַהִיא לְאַלָפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעְבָּדְכוֹן יָתְהוֹן בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@22 וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרֵי לָא חֲזֵיתוּן כָּל דְמוּת בְּיוֹמָא דִי מַלִיל יְיָ עִמְכוֹן בְּחֹרֵב מִגוֹ אֶשָׁתָא:
@23 דִילְמָא תְּחַבְּלוּן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כָּל צוּרָא דְמוּת דְכַר אוֹ נֻקְבָא:
@24 דְמוּת כָּל בְּעִירָא דִי בְאַרְעָא דְמוּת כָּל צִפַּר גַדְפָא דִי פָּרַח בַּאֲוֵר רְקִיע שְׁמַיָא:
@25 דְמוּת כָּל רִחֲשָׁא דִי בְאַרְעָא דְמוּת כָּל נוּנֵי דִי בְמַיָא מִלְרַע לְאַרְעָא:
@26 וְדִילְמָא תִזְקוֹף עֵינָיךְ לִשְׁמַיָא וְתֶחֱזֵי יָת שִׁמְשָׁא וְיָת סִיהֲרָא וְיָת כּוֹכְבַיָא כֹּל חֵילֵי שְׁמַיָא וְתִטְעֵי וְתִסְגוּד לְהוֹן וְתִפְלְחִנוּן דִי זַמִין יְיָ אֱלָהָךְ יָתְהוֹן לְכֹל עַמְמַיָא תְּחוֹת כָּל שְׁמַיָא:
@27 וְיָתְכוֹן קָרִיב יְיָ לְדַחַלְתֵּהּ וְאַפֵּק יָתְכוֹן מִכּוּרָא דְפַרְזְלָא מִמִצְרָיִם לְמֶהֱוֵי לֵהּ לְעַמָא אַחֲסָנָא כְּיוֹמָא הָדֵין:
@28 וּמִן קֳדָם יְיָ הֲוָה רְגַז עֲלַי עַל פִּתְגָמֵיכוֹן וְקַיִים בְּדִיל דְלָא לְמֵעֲבַר יָת יַרְדְנָא וּבְדִיל דְלָא לְמֵיעַל לְאַרְעָא טָבָא דִי יְיָ אֱלָהָךְ יָהֵבּ לָךְ אַחֲסָנָא:
@29 אֲרֵי אֲנָא מָאִית בְּאַרְעָא הָדָא לֵית אֲנָא עָבֵר יָת יַרְדְנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יָת אַרְעָא טָבָא הָדָא:
@30 אִסְתַּמָרוּ לְכוֹן דִילְמָא תִתְנְשׁוּן יָת קְיָמָא דַיְיָ אֱלָהֲכוֹן דִי גְזַר עִמְכוֹן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כֹּלָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@31 אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא אֵל קַנָא:
@32 אֲרֵי תוֹלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן וְתַעְבְּדוּן צֶלֶם דְמוּת כֹּלָא וְתַעְבְּדוּן דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְאַרְגָזָא קֳדָמוֹהִי:
@33 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא אֲרֵי מֵיבַד תֵּיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא לְתַמָן לְמֵירְתַהּ לָא תוֹרְכוּן יוֹמִין עֲלַהּ אֲרֵי אִשְׁתְּצָאָה תִּשְׁתֵּצוּן:
@34 וִיבַדַר יְיָ יָתְכוֹן בְּעַמְמַיָא וְתִשְׁתָּאֲרוּן עַם דְמִנְיָן בְּעַמְמַיָא דִי יְדַבַּר יְיָ יָתְכוֹן לְתַמָן:
@35 וְתִפְלְחוּן תַּמָן לְעַמְמַיָא פָלְּחֵי טַעֲוָתָא עֹבַד יְדֵי אֱנָשָׁא אָעָא וְאַבְנָא דִי לָא יֶחֱזוּן וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין:
@36 וְתִתְבְּעוּן מִתַּמָן יָת דַחֲלְתָּא דַייָ אֱלָהָךְ וְתִשְׁכָּח אֲרֵי תִבְעֵי מִן קֳדָמוֹהִי בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@37 כַּד יֵיעוֹק לָךְ וְיַשְׁכְּחֻנָךְ כֹּל פִּתְגָמַיָא הָאִלֵין בְּסוֹף יוֹמַיָא וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ:
@38 אֲרֵי אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָךְ לָא יִשְׁבְּקִנָךְ וְלָא יְחַבְּלִנָךְ וְלָא יִתִּנְשֵׁי יָת קְיָמָא דַאֲבָהָתָךְ דִי קַיִים לְהוֹן:
@39 אֲרֵי שְׁאֵל כְּעַן לְיוֹמַיָא קַדְמָאֵי דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִי בְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָפֵי שְׁמַיָא וְעַד סְיָפֵי שְׁמַיָא הַהֲוָה כְּפִתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע כְּוָתֵהּ:
@40 הַשְׁמַע עַמָא קַל מֵימְרָא דַיְיָ מְמַלֵל מִגוֹ אֶשָׁתָא כְּמָא דִי שְׁמַעַתְּ אַתְּ וְיִתְקַיָם:
@41 אוֹ נִסִין דִי עֲבַד יְיָ לְאִתְגַלָאָה לְמִפְרַק לֵהּ עַם מִגוֹ עַם בְּנִסִין בְּאָתִין וּבְמוֹפְתִין וּבִקְרָבָא וּבִידָא תַקִיפָא וּבִדְרָעָא מְרָמָא וּבְחֶזְוָנִין רַבְרְבִין כְּכֹל דִי עֲבַד לְכוֹן יְיָ אֱלָהֲכוֹן בְּמִצְרַיִם לְעֵינָיךְ:
@42 אַתְּ אִתְחֲזֵיתָא לְמִדַע אֲרֵי יְיָ הוּא אֱלֹהִים לֵית עוֹד בַּר מִנֵהּ:
@43 מִן שְׁמַיָא אַשְׁמְעָךְ יָת קָל מֵימְרֵהּ לְאַלָפוּתָךְ וְעַל אַרְעָא אַחְזְיָךְ יָת אֶשָׁתֵהּ רַבְּתָא וּפִתְגָמוֹהִי שְׁמַעַתְּ מִגוֹ אֶשָׁתָא:
@44 וָחֳלַף אֲרֵי רְחִים יָת אֲבָהָתָךְ וְאִתִּרְעֵי בִּבְנוֹהִי בַּתְרוֹהִי וְאַפְּקָךְ בְּמֵימְרֵהּ בְּחֵילֵהּ רַבָּא מִמִצְרָיִם:
@45 לְתָרָכָא עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ מִן קֳדָמָךְ לְאָעָלוּתָךְ לְמִתַּן לָךְ יָת אַרְעֲהוֹן אַחֲסָנָא כְּיוֹמָא הָדֵין:
@46 וְתִדַע יוֹמָא דֵין וּתְתוּב לְלִבָּךְ אֲרֵי יְיָ הוּא אֱלָהָא דִשְׁכִנְתֵּהּ בִּשְׁמַיָא מִ לְעֵלָא וְשַׁלִיט עַל אַרְעָא מִלְרָע לֵית עוֹד:
@47 וְתִטַר יָת קְיָמוֹהִי וְיָת פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין דִי יֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ וּבְדִיל דְתוֹרִיךְ יוֹמִין עַל אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ כָּל יוֹמַיָא:
@48 בְּכֵן יַפְרֵשׁ מֹשֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@49 לְמֵעִירוֹק תַּמָן קָטוֹלָא דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵי וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקַמוֹהִי וְיֵעִרוֹק לְחַד מִן קִרְוַיָא הָאִלֵין וְיִתְקַיָם:
@50 יָת בֶּצֶר בְּמַדְבְּרָא בְּאַרְעָא מֵישְׁרָא לְשִׁבְטָּא דִרְאוּבֵן וְיָת רָאמוֹת בַּגִלְעָד לְשִׁבְטָא דְגָד וְיָת גוֹלָן בְּמַתְנָן לְשִׁבְטָא דִמְנַשֶׁה:
@51 וְדָא אוֹרַיְתָא דִי סַדַר מֹשֶׁה קֳדָם בְּנֵי יִשְׂרָאֵל:
@52 אִלֵין סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@53 בְּעִבְרָא דְיַרְדְנָא בְּחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר בְּאַרְעָא דְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן דִי מְחָא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@54 וִירִיתוּ יָת אַרְעֵהּ וְיָת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@55 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְעַד טוּרָא דְשִׂיאֹן הוּא חֶרְמוֹן:
@56 וְכָל מֵישְׁרָא עִבְרָא דְיַרְדְנָא לְמָדִינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא:
@57 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן שְׁמַע יִשְׂרָאֵל יָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְמַלֵל קֳדָמֵיכוֹן יוֹמָא דֵין וְתַלְפוּן יָתְהוֹן וְתִטְרוּן לְמֶעְבָּדְהוֹן:
@58 יְיָ אֱלָהָנָא גְזַר עִמָנָא קְיָם בְּחֹרֵב:
@59 לָא עִם אֲבְהָתָנָא גְזַר יְיָ יָת קְיָמָא הָדָא אֶלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כֻּלָנָא קַיָמִין:
@60 מַמְלָל עִם מַמְלָל מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא:
@61 אֲנָא הֲוֵיתִי קָאֵם בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִדָנָא הַהִיא לְחַוָאָה לְכוֹן יָת פִּתְגָמָא דַיְיָ אֲרֵי דְחֶלְתּוּן מִקֳדָם אֵשָׁתָא וְלָא סְלֶקְתּוּן בְּטוּרָא לְמֵימָר:
@62 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּקְתָּךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עֲבְדוּתָא:
@63 לָא יְהֵא לָךְ אֱלָהּ אָחָרָן בַּר מִנִי:
@64 לָא תַעְבֵּד לָךְ צֶלֶם כָּל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@65 לָא תִסְגוּד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשַׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵּי בָּתַר אֲבָהָתְהוֹן:
@66 וְעָבֵד טֵּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְּרֵי פִקוֹדָי:
@67 לָא תֵימֵי בִּשְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יְזַכֵּי יְיָ יָת דִי יֵמֵי בִשְׁמֵהּ לְשִׁקְרָא:
@68 טַר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@69 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@70 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עֲבִידָא אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְתוֹרָךְ וַחֲמָרָךְ וְכָל בְּעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ בְּדִיל דִי יְנוּחַ עַבְדָךְ וְאַמְתָךְ כְּוָתָךְ:
@71 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וְאַפְּקָךְ יְיָ אֱלָהָךְ מִתַּמָן בִּידָא תַקִיפָא וּבִדְרָעָא מְרָמְמָא עַל כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעְבַּד יָת יוֹמָא דְשַׁבְּתָא:
@72 יַקַר יָת אֲבוּךְ וְיָת אִמָךְ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ וּבְדִיל דְיֵיטַב לָךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@73 לָא תִקְטוֹל נְפָשׁ וְלָא תְגוּף וְלָא תִגְנוֹב (נַפְשָׁא) וְלָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@74 וְלָא תַחְמֵד אִתַּת חַבְרָךְ וְלָא תֵרוֹג בֵּית חַבְרָךְ חַקְלֵהּ וְעַבְדֵהּ וְאַמְתֵהּ תּוֹרֵה וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@75 יָת פִּתְגָמַיָא הָאִלֵין מַלִיל יְיָ עִם כָּל קְהָלְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא עֲנָנָא וַאֲמִיטְתָא קָל רַב וְלָא פְסַק וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהָבִנָן לִי:
@76 וַהֲוָה כַּד שְׁמַעֲכוֹן יָת קָלָא מִגוֹ חֲשׁוֹכָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא וְקָרֶבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְסָבֵיכוֹן:
@77 וַאֲמַרְתּוּן הָא אַחְזְיָנָא יְיָ אֱלָהָנָא יָת יְקָרֵהּ וְיָת רְבוּתֵהּ וְיָת קָל מֵימְרֵהּ שְׁמַעְנָא מִגוֹ אֶשָׁתָא יוֹמָא הָדֵין חֲזֵינָא אֲרֵי יְמַלֵל יְיָ עִם אֲנָשָׁא וְיִתְקַיָם:
@78 וּכְעַן לְמָא נְמוּת אֲרֵי תֵיכְלִנָנָא אֶשָׁתָא רַבְּתָא הָדָא אִם מוֹסְפִין אֲנַחְנָא לְמִשְׁמַע יָת קָל מֵימְרָא דַייָ אֱלָהָנָא עוֹד וּמָיְתִין אֲנַחְנָא:
@79 אֲרֵי מָן כָּל בִּשְׂרָא דִי שְׁמַע קָל מֵימְרָא דַיְיָ קַיָמָא מְמַלֵל מִגוֹ אֶשָׁתָא כְּוָתָנָא וְאִתְקַיָם:
@80 קְרַב אַתְּ וּשְׁמַע יָת כָּל דִי יֵימַר יְיָ אֱלָהָנָא וְאַתְּ תְּמַלֵל עִמָנָא יָת כָּל דִי מַלֵל יְיָ אֱלָהָנָא עִמָךְ וּנְקַבֵּל וְנַעְבֵּד:
@81 וּשְׁמִיעַ קֳדָם יְיָ יָת קָל פִּתְגָמֵיכוֹן בְּמַלָלוּתְכוֹן עִמִי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יָת קָל פִּתְגָמֵי עַמָא הָדֵין דִי מַלִילוּ עִמָךְ אַתְקִינוּ כָּל דִי מַלִילוּ:
@82 לְוַי דִי יְהֵי לִבָּא הָדֵין לְהוֹן לְמִדְחַל קֳדָמַי וּלְמִטַר יָת כָּל פִּקוּדַי כָּל יוֹמַיָא בְּדִיל דִיֵיטַב לְהוֹן וְלִבְנֵיהוֹן לְעָלָם:
@83 אִזֵל אֱמַר לְהוֹן תּוּבוּ לְכוֹן לְמַשְׁכְּנֵיכוֹן:
@84 וְאַתְּ הָכָא קִים קֳדָמַי וֶאֱמַלֵל עִמָךְ יָת כָּלּ תַּפְקֶדְתָּא וּקְיָמַיָא וְדִינַיָא דִי תַלְפִנוּן וְיַעְבְּדוּן בְּאַרְעָא דִי אֲנָא יָהֵב לְהוֹן לְמֵירְתַהּ:
@85 וְתִטְרוּן לְמֶעְבַּד כְּמָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן לָא תִסְטוּן יַמִינָא וּשְׂמָאלָא:
@86 בְּכָל אָרְחָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן תְּהָכוּן בְּדִיל דְתֵיחוּן וְיֵיטַב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דִי תֵירְתוּן:
@87 וְדָא תַפְקֶדְתָּא קְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהֲכוֹן לְאַלָפָא יָתְכוֹן לְמֶעְבַּד בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@88 בְּדִיל דְתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִטַר יָת כָּל קְיָמוֹהִי וּפִקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ אַתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָיךְ וּבְדִיל דְיוֹרְכוּן יוֹמָיךְ:
@89 וּתְקַבֵּל יִשְׂרָאֵל וְתִטַר לְמֶעְבַּד דִי יֵיטַב לָךְ וְדִי תִסְגוּן לַחֲדָא כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@90 שְׁמַע יִשְׂרָאֵל יְיָ אֱלָהָנָא יְיָ חָד:
@91 וְתִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ וּבְכָל נִכְסָךְ:
@92 וִיהוֹן פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין עַל לִבָּךְ:
@93 וּתְתָנִנוּן לִבְנָיךְ וּתְמַלֵל בְּהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@94 וְתִקְטְרִנוּן לְאָת עַל יְדָךְ וִיהוֹן לִתְפִלִין בֵּין עֵינָיךְ:
@95 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@96 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לָךְ קִרְוִין רַבְרְבָן וְטָבָן דִי לָא בְנֵיתָא:
@97 וּבָתִּין מְלָן כָּל טוּב דִי לָא מְלֵיתָא וְגֻבִּין פְּסִילָן דִי לָא פְּסַלְתָּא כַּרְמִין וְזֵיתִין דִי לָא נְצֶבְתָּא וְתֵיכוּל וְתִשְׂבָּע:
@98 אִסְתַּמַר לָךְ דִילְמָא תִנְשֵׁי יָת (דַחַלְתָּא דַ) יְיָ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@99 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִּפְלָח וּבִשְׁמֵהּ תְּקַיַם:
@100 לָא תְהָכוּן בָּתַר טַעֲוַת עַמְמַיָא מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן:
@101 אֲרֵי אֵל קַנָא יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ דִילְמָא יִתְקֵף רָגְזָא דַיְיָ אֱלָהָךְ בָּךְ וִישֵׁצָךְ מֵעַל אַפֵּי אַרְעָא:
@102 לָא תְנַסוּן קֳדָם יְיָ אֱלָהֲכוֹן כְּמָא דִי נַסֵתוּן בְנִסֵיתָא:
@103 מִטַּר תִּטְרוּן יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן וּסְהֶדְוָתֵהּ וּקְיָמוֹהִי דִי פַקְדָךְ:
@104 וְתַעְבֵּד דְכָשַׁר וּדְתַקֵן קֳדָם יְיָ בְּדִיל דְיֵיטַב לָךְ וְתֵעוּל וְתֵירַת יָת אַרְעָא טַבְתָא דִי קַיִים יְיָ לַאֲבָהָתָךְ:
@105 לְמִתְּבַר יָת כָּל בַּעֲלֵי דְבָבָךְ מֵקָדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@106 אֲרֵי יִשְׁאֲלִנָךְ בְּרָךְ מְחָר לְמֵימָר מָא סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהָנָא יָתְכוֹן:
@107 וְתֵימַר לִבְרָךְ עַבְדִין הֲוֵינָא לְפַרְעֹה בְּמִצְרָיִם וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא:
@108 וִיהַב יְיָ אָתִין וּמוֹפְתִין רַבְרְבִין וּבִישִׁין בְּמִצְרַיִם בְּפַרְעֹה וּבְכָל אֱנַשׁ בֵּיתֵהּ לְעֵינָנָא:
@109 וְיָתָנָא אַפֵּק מִתַּמָן בְּדִיל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יָת אַרְעָא דִי קַיִים לַאֲבָהָתָנָא:
@110 וּפַּקְדָנָא יְיָ לְמֶעְבַּד יָת כָּל קְיָמַיָא הָאִלֵין לְמִדְחַל יָת יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָמוּתָנָא כְּיוֹמָא הָדֵין:
@111 וְזָכוּתָא תְּהֵא לָנָא אֲרֵי נִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא כְּמָא דִי פַקְדָנָא:
@112 אֲרֵי יְעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ וִיתָרֵךְ עַמְמִין סַגִיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגָשָׁאֵי וֶאֱמֹרָאֵי וּכְנַעֲנָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי שִׁבְעָא עַמְמִין סַגִיאִין וְתַקִיפִין מִנָךְ:
@113 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וְתִמְחִנוּן גַמָרָא תְגַמַר יָתְהוֹן לָא תִגְזַר לְהוֹן קְיָם וְלָא תְרַחַם עֲלֵיהוֹן:
@114 וְלָא תִתְחַתַּן בְּהוֹן בְּרַתָּךְ לָא תִתֵּן לִבְרֵהּ וּבְרַתֵּהּ לָא תִסַב לִבְרָךְ:
@115 אֲרֵי יַטְעֲיַן יָת בְּרָךְ מִבָּתַר פָּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקֵף רָגְזָא דַיְיָ בְּכוֹן וִישֵׁצָךְ בִּפְרִיעַ:
@116 אֲרֵי אִם כְּדֵין תַּעַבְּדוּן לְהוֹן אֱגוֹרֵיהוֹן תְּתָרְעוּן וְקָמָתְהוֹן תְּתַבְּרוּן וַאֲשֵׁרֵיהוֹן תְּקוֹצְצוּן וְצַלְמֵי טַּעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא:
@117 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ בָּךְ אִתִּרְעֵי יְיָ אֱלָהָךְ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכֹּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@118 לָא מִדְסַגִיאִין אַתּוּן מִכָּל עַמְמַיָא צָבֵי יְיָ בְּכוֹן וְאִתִּרְעֵי בְכוֹן אֲרֵי אַתּוּן זְעֵרִין מִכָּל עַמְמַיָא:
@119 אֲרֵי מִדְרַחַם יְיָ יָתְכוֹן וּמִדִנְטַר יָת קְיָמָא דִי קַיִים לַאֲבָהָתְכוֹן אַפֵּיק יְיָ יָתְכוֹן בִּידָא תַקִיפָא וּפָרְקָךְ מִבֵּית עַבְדוּתָא מִידָא דְפַרְעֹה מַלְכָּא דְמִצְרָיִם:
@120 וְתִדַע אֲרֵי יְיָ אֱלָהָךְ הוּא אֱלֹהִים אֱלָהָא מְהֵימְנָא נָטֵר קְיָמָא וְחִסְדָא לְרַחֲמוֹהִי וּלְנָטְרֵי פִקוֹדוֹהִי לְאַלְפֵי דָרִין:
@121 וּמְשַׁלֵם לְסָנְאוֹהִי טָבָן דִי אִנוּן עָבְדִין קֳדָמוֹהִי בְּחַיֵיהוֹן לְאוֹבָדֵיהוֹן לָא מְאַחַר עֹבַד טָב לְסָנְאוֹהִי טַבְוָן דִי אִנוּן עָבְדִין קָדָמוֹהִי בְּחַיֵיהוֹן מְשַׁלֵם לְהוֹן:
@122 וְתִטַר יָת תַּפְקֶדְתָּא וְיָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבָּדְהוֹן: פפפ:

@1 **ואתחנן.** אין חנון בכל מקום אלא לשון מתנת חנם. אף על פי שיש להם לצדיקים לתלות במעשיהם הטובים, אין מבקשים מאת המקום אלא מתנת חנם. לפי שאמר לו (שמות לג, יט) וחנתי את אשר אחן, אמר לו בלשון ואתחנן. דבר אחר זה אחד מעשרה לשונות שנקראת תפלה, כדאיתא בספרי: **בעת ההיא.** לאחר שכבשתי ארץ סיחון ועוג דמיתי שמא התר הנדר: **לאמר.** זה אחד משלשה מקומות שאמר משה לפני המקום איני מניחך עד שתודיעני אם תעשה שאלתי אם לאו:
@2 **ה' אלהים.** רחום בדין: **אתה החלות להראות את עבדך.** פתח להיות עומד ומתפלל, אף על פי שנגזרה גזרה. אמר לו ממך למדתי, שאמרת לי (שמות לב, י) ועתה הניחה לי, וכי תופס הייתי בך, אלא לפתוח פתח, שבי תלוי להתפלל עליהם, כמו כן הייתי סבור לעשות עכשיו: **את גדלך.** זו מדת טובך וכן הוא אומר (במדבר יד, יז) ועתה יגדל נא כח ה': **ואת ידך.** זו ימינך, שהיא פשוטה לכל באי עולם: **החזקה.** שאתה כובש ברחמים את מדת הדין החזקה: **אשר מי אל** וגו' **.** אינך דומה למלך בשר ודם, שיש לו יועצין וסנקתדרין הממחין בידו כשרוצה לעשות חסד ולעבור על מדותיו, אתה אין מי ימחה בידך אם תמחול לי ותבטל גזרתך. ולפי פשוטו אתה החלות להראות את עבדך מלחמת סיחון ועוג, כדכתיב (דברים ב, לא) ראה החלתי תת לפניך, הראני מלחמת שלשים ואחד מלכים:
@3 **אעברה נא.** אין נא אלא לשון בקשה: **ההר הטוב הזה.** זו ירושלים: **והלבנון.** זה בית המקדש:
@4 **ויתעבר ה'.** נתמלא חמה: **למענכם.** בשבילכם, אתם גרמתם לי. וכן הוא אומר (תהלים קו, לב) ויקציפו על מי מריבה וירע למשה בעבורם: **רב לך.** שלא יאמרו הרב כמה קשה והתלמיד כמה סרבן ומפציר. דבר אחר רב לך הרבה מזה שמור לך, רב טוב הצפון לך:
@5 **וראה בעיניך.** בקשת ממני (פסוק כה) ואראה את הארץ הטובה, אני מראה לך את כלה שנאמר (דברים לד, א) ויראהו ה' את כל הארץ:
@6 **וצו את יהושע.** על הטרחות ועל המשאות ועל הריבות: **וחזקהו ואמצהו.** בדבריך, שלא ירך לבו לומר כשם שנענש רבי עליהם כך סופי לענש עליהם, מבטיחו אני כי הוא יעבור והוא ינחיל: **כי הוא יעבר.** אם יעבור לפניהם ינחלו, ואם לאו לא ינחלו. וכן אתה מוצא כששלח מן העם אל העי והוא ישב (יהושע ז, ה) ויכו מהם אנשי העי וגו' (שם ז, י) , וכיון שנפל על פניו אמר לו קום לך. קם לך כתיב, אתה הוא העומד במקומך ומשלח את בני למלחמה, למה זה אתה נפל על פניך, לא כך אמרתי למשה רבך אם הוא עובר, עוברין, ואם לאו, אין עוברין:
@7 **ונשב בגיא** וגו' **.** ונצמדתם לעבודה זרה ואף על פי כן (דברים ד, א) ועתה ישראל שמע אל החקים והכל מחול לך ואני לא זכיתי למחל לי:
@9 **לא תספו.** כגון חמש פרשיות בתפלין, חמשת מינין בלולב, וחמש ציציות, וכן ולא תגרעו:
@13 **ושמרתם.** זו משנה: **ועשיתם.** כמשמעו: **כי הוא חכמתכם ובינתכם** וגו' **.** בזאת תחשבו חכמים ונבונים לעיני העמים:
@15 **חקים ומשפטים צדיקם.** הגונים ומקבלים:
@16 **רק השמר לך** וגו' **פן תשכח את הדברים.** אז כשלא תשכחו אותם ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעותו אותם מתוך שכחה תחשבו שוטים:
@17 **יום אשר עמדת.** מוסב על מקרא שלמעלה ממנו אשר ראו עיניך, יום אשר עמדת בחורב אשר ראיתם את הקולות ואת הלפידים: **ילמדון.** ילפון, לעצמם: **ילמדון.** יאלפון, לאחרים:
@21 **ואתי צוה ה' בעת ההוא ללמד אתכם.** תורה שבעל פה:
@23 **סמל.** צורה:
@26 **ופן תשא עיניך.** להסתכל בדבר ולתת לב לשוב לטעות אחריהם: **אשר חלק** וגו' **לכל העמים.** להאיר להם. דבר אחר לאלהות. לא מנען מלטעות אחריהם, אלא החליקם בדברי הבליהם לטרדם מן העולם. וכן הוא אומר (תהלים לו, ג) כי החליק אליו בעיניו למצא עונו לשנא:
@27 **מכור.** הוא כלי שמזקקים בו את הזהב:
@28 **התאנף.** נתמלא רוגז: **על דבריכם.** על אודותיכם על עסקיכם:
@29 **כי אנכי מת** וגו' **אינני עבר.** מאחר שמת מהיכן יעבר, אלא אף עצמותי אינם עוברין:
@30 **תמונת כל.** תמונת כל דבר: **אשר צוך ה'.** אשר צוך עליו שלא לעשות:
@31 **אל קנא.** מקנא לנקום אנפרנמנ''ט בלע''ז [חמה] מתחרה על רגזו להפרע מעובדי עבודה זרה:
@32 **ונושנתם.** רמז להם שיגלו ממנה לסוף שמונה מאות וחמשים ושתים שנה, כמנין ונושנתם. והוא הקדים והגלם לסוף שמונה מאות וחמשים והקדים שתי שנים לונושנתם, כדי שלא יתקים בהם (פסוק כו) כי אבד תאבדון וזהו שנאמר (דניאל ט, יד) וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו, צדקה עשה עמנו שמהר להביאה שתי שנים לפני זמנה:
@33 **העידתי בכם.** הנני מזמינם להיות עדים שהתריתי בכם:
@35 **ועבדתם שם אלהים.** כתרגומו. משאתם עובדים לעובדיהם כאלו אתם עובדים להם:
@38 **לא ירפך.** מלהחזיק בך בידיו. ולשון לא ירפך לשון לא יפעיל הוא, לא יתן לך רפיון, לא יפריש אותך מאצלו. וכן אחזתיו ולא ארפנו (שה''ש ג ד) , שלא ננקד ארפנו. כל לשון רפיון מוסב על לשון מפעיל ומתפעל, כמו (מלכים ב' ד, כז) הרפה לה, תן לה רפיון (דברים ט, יד) הרף ממני, התרפה ממני:
@39 **לימים ראשונים.** על ימים ראשונים: **ולמקצה השמים.** וגם שאל לכל הברואים אשר מקצה אל קצה זהו פשוטו. ומדרשו, מלמד על קומתו של אדם שהיתה מן הארץ עד השמים והוא השעור עצמו אשר מקצה אל קצה: **הנהיה כדבר הגדול הזה.** ומהו הדבר הגדול, השמע עם וגו' :
@41 **הנסה אלהים.** הכי עשה נסים שום אלוה, **לבא לקחת לו גוי** וגו' **.** כל ההי''ן הללו תמיהות הן, לכך נקודות הן בחט''ף פת''ח, הנהיה, הנשמע, הנסה, השמע: **במסות.** על ידי נסיונות הודיעם גבורותיו, כגון (שמות ח, ה) התפאר עלי, אם אוכל לעשות כן, הרי זה נסיון: **באותות.** בסימנין להאמין שהוא שלוחו של מקום, כגון (שמות ד, ב) מה זה בידך: **ובמופתים.** הם נפלאות שהביא עליהם מכות מפלאות: **ובמלחמה.** בים, שנאמר (שם יד, כה) כי ה' נלחם להם:
@42 **הראת.** כתרגומו אתחזיתא. כשנתן הקדוש ברוך הוא את התורה פתח להם שבעה רקיעים. וכשם שקרע את העליונים כך קרע את התחתונים. וראו שהוא יחידי, לכך נאמר אתה הראת לדעת:
@44 **ותחת כי אהב.** וכל זה תחת אשר אהב: **ויוצאך בפניו.** כאדם המנהיג בנו לפניו שנאמר (שמות יד, יט) ויסע מלאך האלהים ההולך וגו' וילך מאחריהם. דבר אחר ויוצאך בפניו בפני אבותיו, כמו שנאמר (תהלים עח, יב) נגד אבותם עשה פלא. ואל תתמה על שהזכירם בלשון יחיד, שהרי כתבם בלשון יחיד ויבחר בזרעו אחריו:
@45 **ממך מפניך.** סרסהו ודרשהו להוריש מפניך גוים גדולים ועצומים ממך: **כיום הזה.** כאשר אתה רואה היום:
@48 **אז יבדיל.** נתן לב להיות חרד לדבר שיבדילם. ואף על פי שאינן קולטות עד שיבדלו אותן שבארץ כנען, אמר משה, מצוה שאפשר לקימה אקימנה: **בעבר הירדן מזרחה שמש.** באותו עבר שבמזרחו של ירדן: **מזרחה שמש.** לפי שהוא דבוק, נקודה רי''ש בחטף, מזרח של שמש, מקום זריחת השמש:
@51 **וזאת התורה.** זו שהוא עתיד לסדר אחר פרשה זו:
@52 **אלה העדת** וגו' **אשר דבר.** הם הם אשר דבר בצאתם ממצרים חזר ושנאה להם בערבות מואב:
@54 **אשר בעבר הירדן.** שהוא במזרח, שהעבר השני היה במערב:
@59 **לא את אבתינו.** בלבד **כרת ה'** וגו' **כי אתנו:**
@60 **פנים בפנים.** אמר ר' ברכיה, כך אמר משה אל תאמרו אני מטעה אתכם על לא דבר, כדרך שהסרסור עושה בין המוכר ללוקח, הרי המוכר עצמו מדבר עמכם:
@61 **לאמר.** מוסב על (פסוק ד) דבר ה' עמכם בהר מתוך האש לאמר אנכי ה' וגו' ואנכי עומד בין ה' וביניכם:
@63 **על פני.** בכל מקום אשר אני שם וזהו כל העולם. דבר אחר כל זמן שאני קים. עשרת הדברות כבר פרשתים:
@71 **שמור.** ובראשונות הוא אומר (שמות כ) זכור. שניהם בדבור אחד ובתיבה אחת נאמרו ובשמיעה אחת נשמעו: **כאשר צוך.** קודם מתן תורה במרה: **וזכרת כי עבד היית** וגו' **.** על מנת כן פדאך שתהיה לו עבד ותשמר מצותיו:
@72 **כאשר צוך.** אף על כבוד אב ואם נצטוו במרה שנאמר (שמות טו, כה) שם שם לו חק ומשפט:
@73 **ולא תנאף.** אין לשון נאוף אלא באשת איש:
@74 **ולא תתאוה.** לא תרוג אף הוא לשון חמדה, כמו (בראשית ב, ט) נחמד למראה, דמתרגמנן דמרגג למחזי:
@75 **ולא יסף.** מתרגמנן ולא פסק. כי קולו חזק וקים לעולם. דבר אחר, ולא יסף, לא הוסיף להראות באותו פומבי:
@80 **ואת תדבר אלינו.** התשתם את כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כי ראיתי שאינכם חרדים להתקרב אליו מאהבה. וכי לא היה יפה לכם ללמוד מפי הגבורה ולא ללמוד ממני:
@90 **ה' אלהינו ה' אחד.** ה' שהוא אלהינו עתה ולא אלהי האמות, הוא עתיד להיות ה' אחד, שנאמר (צפניה ג, ט) כי אז אהפך אל עמים שפה ברורה לקרא כלם בשם ה' ונאמר (זכריה יד, ט) ביום ההוא יהיה ה' אחד ושמו אחד:
@91 **ואהבת.** עשה דבריו מאהבה. אינו דומה עושה מאהבה לעושה מיראה. העושה אצל רבו מיראה כשהוא מטריח עליו מניחו והולך לו: **בכל לבבך.** בשני יצריך. דבר אחר בכל לבבך, שלא יהיה לבך חלוק על המקום: **ובכל נפשך.** אפלו הוא נוטל את נפשך: **ובכל מאדך.** בכל ממונך יש לך אדם שממונו חביב עליו מגופו לכך נאמר ובכל מאדך. דבר אחר ובכל מאדך בכל מדה ומדה שמודד לך בין במדה טובה בין במדת פרענות וכן דוד הוא אומר (תהלים קטז, יג) כוס ישועות אשא וגו' (שם קטז, יג) צרה ויגון אמצא וגו' :
@92 **והיו הדברים האלה.** ומהו האהבה והיו הדברים האלה, שמתוך כך אתה מכיר בהקדוש ברוך הוא ומדבק בדרכיו: **אשר אנכי מצוך היום.** לא יהיו בעיניך כדיוטגמא ישנה שאין אדם סופנה, אלא כחדשה שהכל רצין לקראתה. דיוטגמא, מצות המלך הבאה במכתב:
@93 **ושננתם.** לשון חדוד הוא, שיהיו מחדדים בפיך, שאם ישאלך אדם דבר לא תהא צריך לגמגם בו, אלא אמור לו מיד: **לבניך.** אלו התלמידים. מצינו בכל מקום שהתלמידים קרויים בנים, שנאמר (דברים יד, א) בנים אתם לה' אלהיכם, ואומר (מלכים ב' ב, ג) בני הנביאים אשר בבית אל, וכן בחזקיהו שלמד תורה לכל ישראל וקראם בנים שנאמר (ד''ה ב' כט, יא) בני עתה אל תשלו. וכשם שהתלמידים קרויים בנים, שנאמר בנים אתם לה' אלהיכם, כך הרב קרוי אב, שנאמר (מלכים ב' ב) אבי אבי רכב ישראל וגו' : **ודברת בם.** שלא יהא עיקר דבורך אלא בם. עשם עיקר ואל תעשם טפל: **ובשכבך.** יכול אפלו שכב בחצי היום, תלמוד לומר ובקומך. יכול אפלו עמד בחצי הלילה, תלמוד לומר בשבתך בביתך ובלכתך בדרך. דרך ארץ דברה תורה, זמן שכיבה וזמן קימה:
@94 **וקשרתם לאות על ידך.** אלו תפלין שבזרוע: **והיו לטטפת בין עיניך.** אלו תפלין שבראש ועל שם מנין פרשיותיהם נקראו טטפת. טט בכתפי שתים, פת באפריקי שתים:
@95 **מזזות ביתך.** מזוזת כתיב, שאין צריך אלא אחת: **ובשעריך.** לרבות שערי חצרות ושערי מדינות ושערי עירות:
@97 **חצובים.** לפי שהיו מקום טרשין וסלעים נופל בו לשון חציבה:
@98 **מבית עבדים.** כתרגומו מבית עבדותא, ממקום שהייתם שם עבדים:
@99 **ובשמו תשבע.** אם יש בך כל המדות הללו, שאתה ירא את שמו ועובד אותו, אז בשמו תשבע, שמתוך שאתה ירא את שמו תהא זהיר בשבועתך, ואם לאו לא תשבע:
@100 **מאלהי העמים אשר סביבותיכם.** הוא הדין לרחוקים, אלא לפי שאתה רואה את סביבותיך תועים אחריהם הצרך להזהיר עליהם ביותר:
@102 **במסה.** כשיצאו ממצרים שנסוהו במים, שנאמר (שמות יז, ז) היש ה' בקרבנו:
@104 **הישר והטוב.** זו פשרה, לפנים משורת הדין:
@105 **כאשר דבר.** והיכן דבר (שמות כג, כז) והמתי את כל העם וגו' :
@106 **כי ישאלך בנך מחר.** יש מחר שהוא אחר זמן:
@112 **ונשל.** לשון השלכה והתזה, וכן (דברים יט, ה) ונשל הברזל:
@113 **לא תחנם.** לא תתן להם חן. אסור לו לאדם לומר כמה נאה גוי זה. דבר אחר אל תתן להם חניה בארץ:
@115 **כי יסיר את בנך מאחרי.** בנו של גוי כשישא את בתך, יסיר את בנך אשר תלד לו בתך מאחרי. למדנו שבן בתך הבא מן הגוי קרוי בנך, אבל בן בנך הבא מן הגויה אינו קרוי בנך אלא בנה, שהרי לא נאמר על בתו לא תקח כי תסיר את בנך מאחרי:
@116 **מזבחתיהם.** של בנין: **מצבותם.** אבן אחת: **ואשירהם.** אילנות שעובדין אותן: **ופסיליהם.** צלמים:
@118 **לא מרבכם.** כפשוטו. ומדרשו לפי שאין אתם מגדילים עצמכם כשאני משפיע לכם טובה לפיכך חשקתי בכם: **כי אתם המעט.** הממעטין עצמכם, כגון אברהם, שאמר (בראשית יח, כז) ואנכי עפר ואפר, וכגון משה ואהרן שאמרו (שמות טז, ח) ונחנו מה, לא כנבוכדנצר שאמר (ישעיה יד, יד) אדמה לעליון, וסנחריב שאמר (שם לו, כ) מי בכל אלהי הארצות, וחירם שאמר (יחזקאל כח, ב) אל אני מושב אלהים ישבתי: **כי אתם המעט.** הרי כי משמש בלשון דהא:
@119 **כי מאהבת ה'.** הרי כי משמש בלשון אלא. לא מרבכם חשק ה' בכם, אלא מאהבת ה' אתכם: **ומשמרו את השבועה.** מחמת שמרו את השבועה:
@120 **לאלף דור.** ולהלן הוא אומר (דברים ה, ט) לאלפים, כאן שהוא סמוך אצל לשומרי מצותיו, העושין מיראה, הוא אומר לאלף, ולהלן שהוא סמוך אצל לאוהביו, העושין מאהבה, ששכרם יותר גדול, הוא אומר לאלפים: **לאוהביו.** אלו העושין מאהבה: **ולשומרי מצותיו.** אלו העושין מיראה:
@121 **ומשלם לשנאיו אל פניו.** בחייו משלם לו גמולו הטוב כדי להאבידו מן העולם הבא:
@122 **היום לעשותם.** ולמחר לעולם הבא לטול שכרם:

@1 **ואתחנן אל יי' בעת ההיא עד אז יבדיל משה.** ענין התחנה הוא בקשה ותפילה:
@2 **אתה החלות להראות את עבדך וגומ'.** אמר החלות להעיר כי מה שהשיג מזה הוא שעור מעטי ביחס אל גודל השם יתעלה ועוצם ידו וכאלו הוא התחלה לבד לראיית אלו הדברים שזכר כי יותר ויותר לאין שעור יוכל השם יתעלה לעשות מהנפלאות:
@2 **אשר מי אל בשמים ובארץ.** אחשוב כי מלת מי מושכת עצמה ואחרת עמה והרצון בזה אשר מי בשמים ובארץ ומי אל אשר יעשה כמעשיך וכגבורותיך וביאור זה מי הוא זולתך שיהיה מנהיג השמים והארץ בכללות כי אתה לבדך הוא אלוהי השמים ואלהי הארץ כמו שאמ' אברהם וזה כי המלאכים יש להם הנהנה חלקית בשמים ובארץ אך ההנהגה הכוללת בהם הוא לשם יתעלה לבדו כמו שביארנו בחמישי מספר מ"י ומי אשר יעשה כמעשך וכגבורותיך כי המלאכים המניעים הגלגלים יעשו המסודר בהם לבד ולא ישנו את תפקיד' אך השם ית' עשה כל מה שירצה וישנה לפעמים הסדור המסודר מהמלאכי' ההם והוא גם כן עשאם כולם אחר שלא היו כמו שנזכר בפרש' בראשית ומאתו יסודרו כלל כל המעשים. או ירצה בזה מי באלהים בשמי' ובארץ והם המלאכים שיש להם הנהגה מה בשמי' ובארץ המניעים הגלגלים שיוכל לעשו' כמעשיך ובגבורותך וזה שהם לא יוכלו לעשו' כמעשיך כי מעשיך בהנהגת כלל העולם ומעשיהם הם בחלק מה ממנו ולא יוכלו לעשות בגבורותיך במה שתשתנה הסדורים המתחייבים מהם בעשותך הנפלאות והם לא ישנו את תפקידם. ואם באלו שהם היותר נכבדים לא יהיה שישוה לך בזה כ"ש שלא ימצא זה במי שלמטה מהם:
@3 **אעברה נא ואראה את הארץ הטובה אשר בעבר הירדן.** ביאר בזה שארץ ישראל טובה מכל הארצות וענין הטוב אשר בה הוא יתרון הכנה אל שישפע בה השפע האלהי כמו שזכרנו בפרשת שלח לך. ולזה יהיה חושק משה לראות הארץ להוסיף לו שלמות על שלמותו בנבואה ובחכמה:
@3 **ההר הטוב הזה והלבנון.** ידוע כי יער הלבנון היה בהר המוריה ושם היה בית המקדש והנה העי' בזה שזה המקום הוא היותר הנכון שבארץ ישראל ולזה אמר יעקב עליו אין זה כי אם בית אלהים וזה שער השמים. להורות על יתרון הכנת זה המקום אל שישפע בו השפע האלהי ולזה אמר דוד ולציון יאמר איש ואיש יולד בה והוא יכוננה עליון:
@4 **ויתעבר יי' בי למענכם.** כבר ביארנו בפרשת פרה איך היתה הגזרה הזאת על משה בעון ישראל. ויאמר יי' אלי רב לך. ר"ל רב לך חכמה ושפע נבואה במה שהשגת עד שלא יהוה נביא אחר כמך ולזה אין צורך לך לבא בארץ לזאת הסבה כי כבר זכית באלה המעלות למה שלא זכה אחר:
@5 **עלה ראש הפסגה.** כי מה שחשקת לראות את הארץ מצד ידיעתך פריה וטובה הנה תוכל לראותה מראש הפסגה כשתעיין שם לפאת מערב ולפאת צפון ולפאת דרום ולפאת מזרח:
@6 **וצו את יהושע וחזקהו ואמצהו וגו'.** הצואות הם איך יתנהג יהושע במה שיעשהו בהנחילו הארץ לישראל והחזוק והאמוץ ההוא הוא שלא יירא מהמלכיות ההם ושיתחזק ללכת בדרכי התורה:
@7 **ונשב בגאי מול בית פעור.** ר"ל שאז ישכנו בגאי מול בית פעור כשהיה זה והנה זכר זה בעבור מי שיספר אחר זה מענין לכת ישראל אחרי בעל פעור:
@8 **ועתה ישראל שמע אל החקים ואל המשפטים.** הנה החקים מה שאין טעמם מבואר והמשפטים מה שהדין נותן והשכל ישפטהו:
@8 **למען תחיון ובאתם וירישתם.** מגיד שהתועלת בשמיעת אל החקים ואל המשפטים שצוה השם יתעלה הוא השגת החיים האמתיים ראשונה ובעצמות ואולם בשנית ימשך מהתועלת שירשו הארץ:
@9 **לא תוסיפו מן הדבר אשר אנוכי מצוה אתכם.** הזהיר בזה המקום שלא להוסיף דבר על מצות התורה ושלא לגרוע מהם כדי שישמרו מצות התורה בכללם ולזה הוא מבואר שההוספת במצות שיהיה תכלית לשמור מצות התורה לא נמנעה וההוספה במצות שיהיה תכלית לשמור מצות התורה לא נמנעה וההוספת שתכליתה אין לשמור מצות התורה לא נמנעה וכן הענין בגרעון משל ההוספה שאינה לשמור מצות התורה אך להפך כי התורה התירה בעילת אשת יפת תואר אשר ישבנה במלחמה בתנאים שנזכרו בפרשת כי תצא ואם יוסיפו על זאת המצוה ויעשו זה הדין ביפת תואר שלא ישבנה במלחמה הנה זאת ההוספה הוא כנגד כונת התורה וכן אם לוקחו על ארבעה מינים שבלולב מין או מינין אחרים כי אז תפסד כונת התורה. וכן אם חדשו מצוה יש בה קצת הריסת כונת התורה משל ההוספה שהיא לשמור כונת התורה הגדרים שהוסיפו חכמים כמו אמירה לגוי בשבת שהוא שבות ושלא להכין בי"ט להאכיל את הגוי ומה שידמה לזה ויש ג"כ שם קצת מצו' מדרבנן כמו נר חנוכה וקריאת מגלה והכונה בזה ההמשך לכונת התורה שהשתדלה במקומות רבים לפרסם הניסים להוסיף אמונה בשם יתעלה משל הגרעון שאינו לשמור כונת התורה כאלו תאמר שגרעו ממצות יבום וחליצה ויתקנו שאם לא יחפוץ ליבם תהיה אשת המת מותרת לאחר בלא חליצה או שיגרעו כל זאת המצוה בכללה והנה ירבו המשלים על זה משל הגרעון שהוא לשמור כונת התורה שאם יתקנו שתהיה מצות חליצה קודמת למצות יבום מפני ראותם שכונת היבום אינה לשם שמים במייבמים או אם יתקנו שיהיה אסור לבא על יפת תואר קודם שנתגיירה והוא מבואר שלא יוכלו לגרוע מצוה בכללה לשמור כונת התורה ולפי שהוא אפשר שיחשוב חושב שכבר תשלם כונת התורה בזולת המצוה התלויה בארץ אחר שאין נוהגות בכל מושבו' והתורה ראוי שתהיה השלמת התועלת למקיימים אותה באי זה מקום שיהיה הוסיף להזהיר על דבר המצות ההם כאמרו ראה למדתי אתכם חקים ומשפטים כאשר צוני יי' אלהי לעשות כן בקרב הארץ אשר אתם באים שמה לרשתה והם הקרבנות והטמאות והטהרות ומתנות כהונה ולויה:
@10 **עיניכם הרואות את כל אשר עשה יי' בבעל פעור.** ירצה לפי מה שאחשוב שראוי לכם להיות זהירים מאד שלא לפרוץ ולצאת מכוונת התורה כי אתם ראיתם כי אשר היו מכם רודפים אחר הזנות עם בנות מואב שהיו עובדות בבעל פעור השמידו השם יתעלה מקרבך עד שכבר מתו כלם ואתם שהייתם דבקים ביי' ולא רדפתם אחר הזנות חיים כלכם היום לא נפקד איש מאשר לא נמשכו לזה הפועל המגונה וזה ממה שיורה שזה הענין לא היה במקרה כי לא יתכן מה שבקרי שיסכים בכמו זה הרבוי כי מה שבקרי הוא מעטי:
@12 **ראה למדתי אתכם חקים ומשפטים.** כבר זכרנו הסבה למה הוצרך לשנות זה המאמר אשר נכללו בו המצו' התלויות בארץ:
@13 **ושמרתם ועשיתם כי היא חכמתכם ובינתכם.** כבר ביארנו אופן החכמה אשר נשיג בעניין הטמאות והטהרות והקרבנות ומתנות כהונה ולויה מצד היותם בשעור שהוגבלו בו ולזה אמר כי הוא חכמתכם ובינתכם לעיני העמים כי מאלו הדברים נעמוד על חכמת הנמצאות כמו שביארנו:
@13 **אשר ישמעון את כל החקים האלה.** ר"ל אשר יבינו את דבר כל החקים האלה או ירצה בזה כי מי שישמור כל החקים האלה יכיר תכף אופן החכמה בהם מצד מה שהובדל הדבר בהם בקצת הדברים מקצת וכאלו תאמר שהיתה טמאת השרץ למטה מטומאת נבלת הבהמה וטמאת נבלת הבהמה למטה מטומאת נבלת האדם כי זה ממה שיביא להכיר כי בחכמה נפלאה סודר זה הנימוס התוריי:
@14 **כי מי גוי גדול אשר לו אלהים קרובים אליו.** הרצון בזה כי הגוים מצד היותם תחת ההשגחה הכוללת לבד לא יהיו נעזרים מהשם יתעלה רק בטובות המסודרות מצד השגחה ההיא אבל ישראל שהם תחת ההשגחה הפרטית הם נעזרים בכל מה שיבקשו מהשם יתעלה וזהו אמרו בכל קראנו אליו רוצה לומר בכל מה שנשאל ממנו:
@15 **ומי גוי גדול אשר לו חקים ומשפטים וגו'.** אמנם אמר זה לפי שתורתנו השלמה היא מסודרת על צד היושר והחכמו' ולזה לא תכב' על מקיימ' כי עצם דברי ה' גוזר על ההמשך אחריהם ואין העניין כן בתורות שאר האומות ונימוסיהם שאינם מסודרים מהיושר והחכמה ויעמיסו עם זה על בני הנימוס דברי' יכבדו מאד כאמרו כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם:
@16 **רק השמר לך ושמור נפשך מאד וגו'.** הרצון בזה שישמרו נפשם שלא ישכחו מעמד הר סיני הנפלא אשר העיד על היות התורה מסודרת מהשם יתעלה כי כל העם ראו את הקולות ואת הלפידים ושאר המופתים שנעשו שם ולזה צוה אותם שיודיעו זה לבניהם דור אחר דור כי זאת היא פנה גדולה בענין התורה:
@19 **קול דברים אתם שומעים ותמונה אינכם רואים זולתי קול.** הנה אמר זה להרחיק התמונה מהשם יתעלה כי אינו בעל גוף שתהיה לו תמונה ואותי צוה יי' בעת ההיא ללמד אתכם וגו'. הנה רמז בזה מה שנאמר שם למשה ואלה המשפטי' אשר תשים לפניהם ויתר המצות שנאמרו שם למשה אשר קצתם אינם נוהגות אלא בארץ:
@22 **ונשמרתם מאד לנפשותיכם.** רוצה לומר שתשמרו מזה בעבור נפשותיכם שיאבדו בזה החטא רצוני לומר אם תתנו תמונה לשם יתעלה:
@23 **פן תשחיתון ועשיתם וגו' תמונת כל סמל.** הוא כמו צלם תבנית זכר או נקבה ירצה לפי מה שאחשוב תבנית איש או אשה ואחר זה ירד מהדרגה וזכר תחלה הב"ח ההולך ואחר זכר תבנית המעופף ואחריו תבנית הדגה ושם רמש האדמה בין המעופף והדג לפי שהוא יותר פחות במציאותו מהמעופף ולזה תמצא ברבים מהם שהם מולידים ביצה בלתי שלמה כמו הענין בדגים:
@26 **ופן תשא עיניך השמימה וראית את השמש וגומ'.** רוצה לומר כי כשתראה ותתבונן בענין הכוכבים אשר ישפיע השם יתעלה באמצעותם הרבה מהנמצאות השפלות וסודרו מה' הרבה מהמקרים והמשיגים אשר יקרו לאומה אומה אולי תטעה ותתן להם אלהות או אחד מהם והשתחוית להם ועבדתם כמו שעשו הרבה מהקודמים והזכיר השמש תחלה כי פעולותיו יותר גלויות בענינים הקודמים והטבעים ואחריו היה הירח בזה הענין ואחריהם כוכבי לכת ושאר הכוכבים אחריהם והנה אמר כי זה עם שהוא טעות לכל האנשים אשר יתנו להם אלהות הוא טעות יותר נפלא לישראל וזה כי שאר האומות חלק להם השם יתעלה אלו הכוכבים ולזה אפשר להם לטעות לעשות אלוה מהכוהב המושל עליהם כאלו תאמר שעם כך תחת ממשלת כוכב פלוני ולפי הוראתו לטוב או לרע יהיה ענין האומה ההיא על הרוב ואין הענין כן בישראל כי הם אינם תחת ממשלת הכוכבים כי השם יתעלה לקחם והוציאם מכור הברזל ממצרים להיות לו לעם נחלה במה שמשך אותם לאמונתו ועבודתו בעניין הנפלאות והמופתים שחדש בהוציאו אותם מארץ מצרים ובתורתו השלמה שנתן להם ומפני זה אין ישראל תחת ממשלת הכוכבי' כי השגחת השם יתעלה דבקה בהם מזה הצד:
@28 **ויי' התאנף בי** גללכם. כבר בארנו למה הוצרך משה לומ' להם בכל פעם שזה העונש השיגהו מצדם והנה הורך להזכיר זה בזה המקום להודיע להם שהוא משתדל שאחר מותו לא יעשו זה העון הנפלא רוצה לומר לעבוד עבודה זרה ולזה הודיעם בזה המקום שהוא מת בארץ ההיא אך הם יעברו את הירדן והוכיחם והזהירם שלא ישכחו את יי' מרוב הטובה שתהיה להם שם ויעבדו עבודה זרה אשר צוה הש' יתעלה שלא יעבדוה כי השם יתעלה יעניש עובדי עבודה זרה עונש נפל כמו האש שתשחית כל מה שתלקח בו כן ישחיתם:
@32 **כי תוליד בנים ובני בנים ונושנתם בארץ וגומר.** רה איך ראתה התורה עבוד ישראל עבודה זרה אחר שארכו להם הימים בארץ והתחכם השם יתעלה לפי מה שאפשר להצילם מזה:
@33 **העידותי בכם היום את השמים ואת הארץ.** לפי שהשמים והארץ עומדים לעולם וקיימים נתנם עדים על זה הייעוד הרע להעיד שכבר נתקיים להם זה הייעוד:
@34 **והפיץ יי' אתכם בעמים וגו'.** הנה עונותיהם הטו שכבר נתקיים זה הייעוד הרע בגלות עשרת השבטים שלא נשאר מהם כי אם מתי מספ' כמו שנזכר בספר מלכי' ובגלות ראשון שגלו לבבל והוכרחו שם להשתחוות לצלם כמו שנזכר בספר דניאל ואליהם ידמה שרמז בזה המקום וכבר נתקיים קצתו בימי השופטים ומצאנו כי תכף שהיו מבקשים את יי' בכל לבבם ובכל נפשם היה השם יתע' שולח להם מושיע כמו שנזכר בספר שופטים:
@37 **בצר לך ומצאוך כל הדברים האלה באחרית הימים.** בז המקום רמז אל הגלות הזה הארוך אשר אנחנו בו היום נפוצים בעמים בחטאינו ובעונות אבותינו ולזה אמר באחרית הימים להעיר על שזה יהיה אחר זמן ארך אורך נפלא:
@37 **ושבת עד יי' אלהיך ושמעת בקולו.** רוצה לומ' שאז תשוב אל השם יתעלה ותקיים מצותיו והנה השם יתעלה אל רחום לא יסור השגחתו ממך מכל וכל:
@38 **ולא ישחיתך.** השחתה כוללת על עונותיך ולא ישכח את ברית אבותיך אשר נשבע להם לתת לזרעם אחריהם ארץ כנען ומבריתו את האבות יתחייב שלא יכלה אתכם כי תופר בריתו בזה. העניין והראיה לך על שומרי בריתו את האבות הנפלאות אשר עשה לך בצאתך ממצרים שלא היו מצד זכותך שתדבק בך כמו זאת ההשגחה הנפלאה אבל יהיו מצד ברית השם יתעלה עם האבות כמו שנתבאר בפרשת ואלה שמות:
@39 **כי שאל נא לימים ראשונים.** אם קרה כך מעת בריאת העולם באחד ממקומות הארץ שישמע עם קול אלהים מדבר מתוך האש כמו ששמעת אתה במעמד הר סיני כי זה דבר לא נהיה כלל והיה גם כן מן הפלא שהיית אחר דבר אלהיך עמך וכבר היה מפורסם אז כי מי שיראה אלו המראות הנפלאות ימות תכף ולזה אמר יעקב כי ראיתי אלהים פנים אל פנים ותנצל נפשי ואם נסה השם יתעל לקחת לו גוי מקרב גוי על ידי נפלאות רבות המספר כמו שעשה לך השם יתעלה בהוציאו אותך ממצרים ועיניך רואות והנה עשה זה השם יתעלה מצד בריתו עם האבות כמו שזכרנו להביא אותך למדרגה שתאמין בשם יתעל אתה הראית אלו הנפלאות לתכלית שתדע כי יי' הוא האלהים והוא שליט בארץ כמו שהוא שליט בשמים וכבר עמדת על זה מצד הפלאות שחדש לך בארץ כי זה מופת כי ליי' הארץ:
@42 **אין עוד מלבדו.** שלא יחשוב חושב כי יש אלהים בשמים מנהיג השמים ויש אל אחר בארץ מנהיג הארץ כי זה הוא שקר אך השם יתעלה הוא המנהיג השמים והארץ אין עוד מלבדו וכבר יעיר על זה כי השם יתעלה שנה הסדורים אשר בארץ מפאת הכוחות השופעות שם מהגלגלים וזה דבר לא יכול עליו אם לא היה שליט בשמים ובארץ וזה ממה שצריך אל ביאור יותר רחב אך במה שזכרנו בו די לזאת הכונה בזה הביאור כי לא יכול האריכות הצריך בזה ובמה שידמה לו:
@43 **מן השמים השמיעך את קולו ליסרך.** רוצה לומר כי במעמד הר סיני השמיעך השם יתעלה את קולו מן השמים לתת לך הנימוס התוריי בדעות ובמדות אשר נכלל כלו בעשרת הדברים ההם כמו שביארנו בפרשת יתרו:
@43 **ועל הארץ הראך את אשו הגדולה.** שנראה לך שם ושמעת את דברו מתוך האש וזה לך גם כן לאות כי הוא בשמים ובארץ:
@44 **ותחת כי אהב את אבותיך וגומ'.** הנה לאהבת השם יתעלה את אבותיך ובחר בזרע האבות המיוחס להם והוא זרע יעקב הנה הוציאך ממצרים בפניו רוצה לומר בהשגחתו הפרטית שהוא מיוחסת אל פניו כי המביט מביט בפניו וזהו כוחו גדול כי מפאת זאת השגחה יתחדשו הנפלאות:
@45 **להוריש גוים גדולים ועצומים.** הנה נעשה זה לתכלת שתירשו תכף את הארץ מיד הגוים הגדולים העצומים ההם כמו שראית בעיניך היום הזה שירשת ארץ שני מלכי האמורי:
@46 **וידעת היום והשבות אל לבבך כי יי' הוא האלהים.** רוצה לומר אחר שהשם יתעלה הראך את כל זה להודיעך כי הוא אלהי השמים ואלהי האר אין עוד זולתו באלהות הנה צריך שתדע זה ותשיב אל לבבך כי יי' הוא האלהים בשמי ממעל ועל הארץ מתחת אין עוד כמו שיחשבו המאמינים בשניות שיהיו שנים אלהי השמים זולת אלהי הארץ וכבר ביאר הפילוסוף מום זאת האמונה וביאר שהענין הוא כן כמו שהגיד בספרו מה שאחר הטבע ואין הנה מקום זאת החקירה ובהיות הענין כן הנה ראוי לך לשמור מצותיו וחוקיו לטוב לך ולזרעך והנה זאת הטובה הוא בעצמות מה שהוא טוב אנושי והוא הצלחת הנפש וימשך לו ג"כ טוב גופיי בעבור דבקות השגחה האלהית והוא ששמירת חקיו ומצותיו יסבב שתאריכו ימים על האדמה בדרך שתהיה לכם ולזרעכם כל הימים והוא מבואר כי לולי עבור אבותינו על דברי התורה היינו אנחנו מחזיקין בארץ ישראל ולא גלינו ממנה והוא מבואר מספורי דברי הנביאים. הנה זה ביאור זאת הפרשה.
@48 **ספר** שכבר הבדיל משה אז השלשה ערים שצוה השם יתעלה להבדיל מעבר הירדן מזרחה לנוס שם כל מכה נפש בשגגה בלא כוונה אשר אינו שונא לו מתמול שלשום שאם היה שונא לו אולי סבב הרוצח השגגה בכוונה שאם יקרה שיעבור שם השונא לו ינזק ובזה התנאי ימלט הרוצח בעיר מקלטו מיד גואל הדם אמנם אם הרג מזיד אף על פי שנס אל עיר מקלטו ישפטוהו הסנהדרין ויתנוהו ביד גואל הדם להמיתו כמו שהתבאר בפרשת מסעי והם בצר ורמות וגולן כמו שצוה השם יתעלה.
@51 **וזאת התורה.** שסדר משה לפני בני ישראל והם העדות והחקים והמשפטים אשר דבר משה אל בני ישראל בצאתם ממצרים כי אז נתנה התורה בכללות ואולם סדר משה לפני בני ישראל אותם הדברים שנאמרו אז בעבר הירדן בגאי מול בית פעור והנה תאר המקום ההוא בתארים רבים מודיעים אותו להוסיף אמות בזה הספור ובזה המקום יתבאר כי כל מה שנזכר בזה הספר נתן למשה בהר סיני אך בקצתו הוסיף ביאור בזה המקום במה שאמ' בעבר לירדן בארץ מואב הואיל משה באר את התורה הזאת לאמר וראוי היה להיות כן כי התורה מצד היותר נימוס אחד כולל לתכלית אחר מוגבל הנה יחוייב שיהיה סדורו יחד לא פעמים בפעמים כמו שנזכר בפרשת בראשית:
@57 **שמע ישראל את החקים ואת המשפטי' אשר אנכי דובר באזניכם היום ולמדתם אותם.** למדנו מזה שחייב אדם ללמד תורה לא ללמוד לבד עם שבמצות הלמוד לאחרים נכללה מצות הלמידה כי מי שלא למד לעצמו לא יוכל ללמוד לאחרים:
@59 **לא את אבותינו כרת את הברית וגומ'.** הרצון בזה כי לא נתנה התורה לאבות לבד אך להם ולזרעם אחריהם לאין תכלית ולזה ראוי שיחשוב כל דור ודור כאלו לו נתנה התורה:
@61 **אנכי עומד בין יי' וביניכם בעת ההיא וגומ'.** הנה זה היה בעת שאמרו לו ישראל דבר אתה עמנו ונשמעה כי יראתם מפני האש הנה מפני זה נתבאר בפרש' יתרו שיראו העם ועמדו מרחוק אחרי שמעם מפי הגבורה זה הקול הנפלא עשרת הדברים באמרו את הדברים דבר יי' אל כל קהלכם בהר מתוך האש בענן ובערפל:
@61 **ולא עליתם בהר.** רוצה לומר כי אף על פי שלא עליתם בהר לא יה לכם רשות לעלות בו אף על פי כן יראתם והנה אמר זה להעיר שאם היו מסכימים לשמוע כל דברי הורה מפי השם יתעלה היו שומעים אותם כמו ששמעו עשרת הדברם כי לא עשה זה השם יתעלה ליראם ולבהלם לכוונה שיברחו מלשמוע והראיה כי משה היה בהר וישראל לא עלו בהר ולזה לא היה להם לירוא כל כך ולזה הוא מבואר שכבר היה לישראל להאמין שאר מצות התורה כמו האמנתם עשרת הדברים ששמעו אותם מפי הגבורה:
@61 **הנה** כבר ביארנו כל זה ותועלותיו בפרשת יתרו ומשם ילקח הביאור בו זולתי מעט שבא בזה המקום והוא שכבר אמר פה שמור תמורת אמרו זכור בפרשת יתרו ולזה יהיה הרצון באמרו לקדשו שתקדשהו בדברים כדי שתשמור את השבת ולזה יחוייב שיהיה זה הקדוש סמוך לכניסתו כדי שיזכיר כי שבת הוא וישמור מעשות מלאכה בו ומזה המקום למדו רבותינו זכרונם לברכה שהנשים מחוייבות בקדוש היום כי הן מחוייבות בתכלית אשר בעבורו צותה התורה לקדשו בדברים והיא השמירה מעשות בו מלאכה:
@61 ועוד נתחדש בו גם כן בפרשת יתרו נתן הסבה בענין מצוות השבת להזכיר לנו כי השם יתעלה חדש העולם בשבת ימים וביום השביעי שבת וינפש כי זאת פנה גדולה מפנות התורה רוצה לומר אמונת החדוש ואולם בזה המקום נתן הסבה במצות שבת לזכור המופתים שעשה לנו השם יתעלה בהוציאו אותנו מארץ מצרים כי אז היינו עבדים ולא היה לנו רשות לנוס מהעבודה הקשה אשר היה מעביד אותנו פרעה ועמו והנה אין זה סתירה בחק התורה וזה כי התורה תצוה מה שתצוה לתועלות רבים כאשר היה אפשר לה זה כמו העניין בטבע שישתמש לפעמי' במה שיעשהו לתועלת יותר מאחר כמו שנזכר בספ' בעלי חיי':
@74 **ולא תתאוה.** הנה התאוה היא בלב לבד ולפי מה שביאר' בפר' יתרו מההדרגה באלו הדברות ראוי שתתברר שהתאוה מביאה לידי חמוד והנה ההבדל שיש בין החמוד ובין התאוה הוא כי התאוה הוא בלב לבד והחמוד הוא לקיחת דרך שיגיע לו הדבר שהיתה בו התאוה ויוציא זה לפועל כאלו תאמר שישתדל עם האיש ההוא בעל הבית שיוכרח למכור לו ביתו או שדהו או מה שהתאוה וזה יהיה אם בהבאתו לו אנשים יבקשו ממנו זה לא יוכל להשיב פניה' או במה שידמה לזה והראיה בזה שדבר החמוד דבר שיש בו מעשה מה שאמר ולא יחמוד איש את ארצך בעלותך לראות את פני יי' אלהיך ואמר לא תחמוד כסף וזהב עליהם ולקחת לך:
@75 **קול גדול ולא יסף.** רוצה לומר שלא יסף להתחדש שם קול אחר קול אך הקול ההוא היה נמשך ומתדבק בזולת הפסקים וגם כן לא פסק הקול ההוא אחר דברו עשרות הדברים אך היה נמשך אל ישראל להתרחקו מעל המקום ההוא שלא ישמעוהו והנה אמר זה להוסיף אמות לישראל שכל התורה היה אפשר להם לשמוע בזה האופן לולי יראתם מפני האש והקולות הנפלאים ההם כמו שקדם או יהיה הרצון באמרו ולא יסף שלא יסף עוד להתחדש כמו זה הקול הנפלא מהשם יתעלה באופן שישמעו דבריו כלל עם אחד והביאור הראשון ידמה שיהיה נאות יותר ואם שניהם כאחד טובים:
@76 **כשמעכם את הקול מתוך החשך.** הוא הערפל שזכר תחלה כאמרו מתוך האש הענן והערפל ויכתבם על שני לוחות אבנים ביאר בזה כי המכתב אשר בלוחות לא היה נעשה במלאכה אך השם יתעלה חדש המכתב ההוא בהם על דרך המופת וזה גם כן עוד לאות על שנתנו אלו הדברים מהשם יתעלה ובזה אמר במה שקדם והלוחות מעשה אלהים המה והמכתב מכתב אלהים הוא חרות על הלוחות:
@77 **ותאמרו הן הראנו יי' אלהינו את גדלו ואת כבודו וגומ' ואת תדבר אלינו את כל אשר ידבר יי' אלהינו אליך ושמענו ועשינו.** הנה התחלה אמרו כל אשר ידבר יי' נעשה להעיר שלא יאמינו רק מה אשר יתברר להם אשר דברו יי' ולזה הוצרכו להתחדש אלו הקולות הנפלאים כדי שישמע העם אלו הדברים מהשם יתע' אך אחר שראו זה הפלא וייראו מלשמוע השאר בזה האופן פן ימותו והאמינו במשה ואמרו לו שישמע הוא הדברים מהשם יתעלה ויביאם אליהם והם ישמעו דברי משה ויעשו אותם:
@82 והנה ספר שיישר בעיני יי' מה שאמרו למשה **מי יתן והיה לבבם זה ליראה אותי** ולמדנו מזה שהדברים המיוחסים אל הבחירה אין השם יתעלה מבריח אחד מחלקי האפשר על דרך החיוב שאם היה הענין כן לא היה אומר השם יתעלה מי יתן והיה לבבם זה להם שכבר היה זה ביד השם יתעלה לפי זאת ההנחה רוצה לומר לחייב שתהיה בחירתם תמיד אל ההמשך בדרכי התורה ואף על פי שמצאנו שהשם יתעלה יטה הבחירה בעת מה למי שירצה כמו שמצינו בהקשותו לב פרעה וסיחון ומה שידמה לזה הנה זה הוא על דרך המופת ומה שזה דרכו לא יהיה תמיד כמו שביארנו בששי מספר מלחמותיי':
@82 **ולשמור את כל מצותי כל הימים.** למדנו מזה שאלו המצות בכללם רצה השם יתעלה שיעמדו כל הימים כי עליהם אמר זה המאמר ולזה הוא מבואר שלא ימיר השם יתעלה את התורה ולא מצוה ממצותיה ולבניהם לעולם רוצה לומר כל הימי' וזה מבואר מהפסוק' בעצמו:
@83 **לך אמור להם שובו לכם לאהליכם.** אמר זה שכבר הוזהרו מלגשת אל אשה קודם זה כדי שיהיו נכונים לשמוע דברי השם יתעלה כאמרו היו נכונים לשלשה ימים אל תגשו אל אשה ואחר שנפרדו מאלו הדברים הקדושים הותרו לגשת אל נשותיהם:
@84 **ואתה פה עמוד עמדי.** ביאר בזה שהם לבדם הותרו לשוב לאהליהם לא משה כי תמיד היה עם השם יתעלה ומדבר עמו ולזה היה ראוי שיהיה מקודש לנבואה תמיד ולזה פרש משה מן האשה כמו שיראה ממה שדברו אהרן ומרים במשה על אודות האשה הכושית אשר לקח שפרש ממנה כמו שנזכר בסוף פרשת בהעלותך:
@84 **ואדברה אליך את המצוה ואת החוקים והמשפטים אשר תלמדם ועשו בארץ.** ידוע כי במצוה האחת חקים ומשפטים אשר תלמדם ועשו בארץ. ידוע כי במצוה האחת חקים ומשפטים כמו שמצאנו במצות קרבן שנאמר בה ככל חקותיו וככל משפטיו תעשו אותו כחקת הפסח וכמשפטו כן יעשה והנה אמר אשר תלמדם ולא אמר אשר תדבר אליהם להעיר שמשה היה מלמד לישראל המצוה ופרושיה ודקדוקיה ולזה אמר הואיל משה באר את התורה הזאת וזהו אמרו גם כן וזאת המצוה והחקי' והמשפטים אשר צוה יי' אלהיכם ללמד אתכם ולא אמר להגיד לכם ולזה רמז לפי מה שאחשוב אמרו הואיל משה באר את התורה וגומ' כי אז למדה וביארה וגלה סתומיה ועמוקותיה:
@85 **לא תסורו ימן ושמאל.** רמז בימין אל ההוספה ובשמאל אל הגרעון כי המוסיף יחשוב לעשות טוב כי הוא עושה מצות השם יתעלה ויותר מזה והוא יפסיד בזה כוונת התורה כמו שזכרנו במה שקדם:
@86 **למען תחיון וטוב לכם והארכתם ימים בארץ.** ידמה כי רמז באמרו למען תחיון בחיי הנפש והם הטוב אמתי באדם במה שהוא אדם ובהארכת הימים בארץ רמז אל הטיוב הגופיי המישיר אל הטוב הנפשיי:
@88 **אתה ובנך ובן בנך וכל ימי חייך.** רוצה לומר כל הדורות הנמשכים ממך זה אחר זה ולזה אמר אתה ובנך ובן בנך והנה הוא כאלו אמר כל הימים אשר יתקיים לך זה אחר זה הנה זה באור מה שיצטרך אל ביאור לזאת הפרשה:
@90 **שמע ישראל.** הכוונה בו ההאמנה והשמיעה יבינו בו על צד הבנה וההמון יאמינו בו על דרך צד השמיעה והקבלה מהיחידים:
@90 **יי' אלהינו.** צוה בזה להאמין כי מי שנקר שמו יי' הוא אלהינו רוצה לומר שהוא מנהיג אותנו ומשגיח בנו ואף על פי שאנחנו פחותים ביחס מאד אל מעלתו יתעלה וכבר נתאמתה זאת הפנה והותרו הספקות הנופלות בה ברביעי מספר מלחמות יי' וכבר בארנו בפרשת ואלה שמות שזה השם רוצה לומר יו"ד ה"א וא"ו ה"א הוא היותר מורה על מהות השם יתעלה מכל השמות שיפלו וכן הענין בשם האחד כמו שביארנו שם ובביאורנו למה שאחר הטבע:
@90 **יי' אחד.** צוה בזה להאמין שהנמצא הקדוש הזה שנקא בזה השם הקדוש הוא אחד וראוי שלא יעלם ממנו שכבר יתבאר מזה שכמו שלא ישתת וזולתו יתעלה בשם יו"ד ה"א וא"ו ה"א כן לא ישתתף זולתו שם האחד כי שני אלו השמות יאמרו בו יתעלה באמתת ובקדימה ויאמרו על זולתם באחור בצד מצדדי שתוף השם יתעלה וזה כי כל הנמצאות קנו האחדות והמציאות ממנו ולזה יהיה הוא יתעלה היותר אמתי באלו השמות ואם אמר אומר כי גם המניעים הנבדלים הם אמתיים בשם האחד כי אין בהם שום הרכבה כמו שאין הרכבה בשם יתעלה אמרנו לו כי אלו מצד מה שהם עלולים ממנו יחוייב להם בהשיגם עצמם שישיגו היותם עלולים ומזה הצד תהיה להם השגה מה בהכרח בעלה הראשונה כמו שביארנו בחמישי מספר מלחמות יי' ולזה יהיו מרכבים משני עניני' עניין בו ישכילו עצמם וענין בו ישכילו זולתם ואולם השם יתעלה לא ישיג כי אם עצמו כי אין לו עלה קודמת לזה הוא יותר ראוי אמתי בשם האחדות עם שהאחדות אשר לאלו הוא חסר מאד ביחס אל האחדות הנכבד אשר לשם יתעלה כמו שביארנו כל זה בראשון ובחמישי מספר מלחמות יי' ואם אמר אומר שבשם יתעלה הרכבה מזה הצד מצד השגתו בעלולים ממנו אמרנו לו שאין לו בהשגת העלה הזאת שהיא שכל העלולים ממנה שום הרכבה כי מצד השיגה עצמה תשיג העלולים ממנה מצד היותר נכבד ממציאותם כמו שביארנו שם ואין הנה מקום זאת החקירה:
@91 **ואהבת את יי' אלהיך.** צונו בזה המאמר לאהוב השם יתעלה ולפי שהאהבה מבואר מענינה שלא תהיה לדבר שאין בו שום השגה כל שכן כשלא תהיה בזה האופן השלם אשר זכר פה הנה יחוייב זה הציווי שנעשה בדרך שתהיה לנו השגה מה בזה השם הנכבד והנורא כדי שנתעורר מפני זה לאהבו וכל מה כשנוסף האהבה בו יתעלה נוסיף לאהבה אותו והנה זה יושג לנו מצד שקדנו על מצוות התורה כי הם יישירונו אל השגתו יתעלה כמו שביארנו בזה בזה הספר ומצד החקירה על פעולות השם יתעלה הנפלאות המושגות לנו מענין אלו הנמצאות אשר אצלנו והוא מבואר כי כשיעמוד האדם על זה תהיה אהבתו יתעלה יותר חזקה מכל האהבות אשר אצלו כי סבות האהבה הם השלמות והמעלה והערבות והתועלת כמו שנזכר בספר המדות. ולפי שהשם יתעלה הוא בתכלית השלמות והמעלה עד ששלמות כל נמצא זולתו חסרון ביחס אל שלמותו יתעלה הנה יהיה היותר נאהב לאין שעור מזה הצד ולפי שהערבות אשר תהיה בהשגתו יתעלה למעלה מכל הערביות לאין שיעור כמו שביארנו בחמישי מספר מלחמות השם ובביאורינו למה שאחר הטבע הנה יהיה היותר נאהב לאין שעור מזה הצד ולפי שהתועל' שיושב מהשגתו יתע' למעלה מכל התועלות כי הוא השגת החיים הניצחיים הנה יהיה היותר נאהב לאין שעור מזה הצד עם שהוא המשפיע לאדם כל הערביות והתועלות שיושגו לו והוא הממציא אותו והשומר מציאותו הזמן האפשרי לו:
@91 **בכל לבבך.** ידוע כי הלב יאמר על הרצון והנה באדם שני מינים מהרצון והחפץ האחד הוא הכח המתעורר שהוא נמשך לציור הדמיון והשני הוא הכח המתעורר שהוא נמשך לציור השכל וכבר יראה האדם לפעמים בעצמו שני אלו הכחות יחד ויחלוק זה עם זה וברעים יגבר היצר הרע ובטובים ינצח היצר הטוב וכאלו הזהיר בזה וצוה שיכניע האדם כל מיני רצונו לאהבת השם יתעלה וימשך מהאהבה הזאת שישמור מצותיו כי האוהב ישתדל לעשו' רצון אוהבו כפי היכולת:
@91 **ובכל נפשך ובכל מאודך.** לפי שהרצון באמרו ובכל מאודך שלא יחוש אם יפזר כל מאודו או יפסידהו לאהבת השם יתעלה הנה יתבאר מזה שהרצון באמרו בכל נפשך שהוא אפי' יטלו את נפשו וימיתוהו לא יחוש לאהבת השם הנכבד ולשמור מצותיו ויהיה אמרו בכל נפשך מענין אמרו כי בנפשו דבר אדוניהו וכבר ביארנו התנאים אשר בהם יתיר האדם עצמו למיתה לאהבת הש' יתעלה בפרשת אמור אל הכנים והוא מבואר שאין הרצון באמרו בכל נפשך מענין רצון על דרך מה שאמר אם יש את נפשכם שהוא כמו רצונכם שאם היה זה כן יהיה אמרו בכל נפשך לבטלה כי כבר אמר תחלה בכל לבבך:
@92 **והיו הדברים האלה אשר אנכי מצוך היום על לבבך.** צוהו שיהיו אלו הדברים אשר צוה בזה המקום תמיד אצל לבבנו ומחשבתנו כדי שלא נשכח אותם כי הם מהגדולות שבפנות התורה ולפי שאמ' אחר זה לדבר בם ולכתבם בתפלין ובמזוזות והתנה בזה המקום ואמר והיו הדברים האלה למדנו מזה שאין ראוי להמיר בהם סדר אלו הדברים ולא להמיר הלשון בלשון אחר כי כל זה הוא נכלל באמרו והיו הדברים האלה:
@93 **ושננתם לבניך.** הוא מענין למוד וקראו שנון מצד השנות הדברים הצריכים בלמוד כי אם לא ידע בפעם אחת ישנה לו או ישלש עד שילמוד מה שצריך למדו ומזה המקום יתבאר שצריך גם כן שילמדם וידעם האדם כי מי שלא ידע לעצמו לא יוכל ללמד לאחרים עם שהוא מן השקר שתצוה התורה שיעדו קטנים אלו הפנות הגדולות ולא תצוה שידעו הגדולים לפי שבנים נאמר על התלמידים כמו שמצאנו שנקראו תלמידי הנביאים בני הנביאים ידענו שכבר כלל זה הצווי גם כן שילמדם לתלמידיהם וזה גם כן נכנס בצווי ואהבתו כי האוהב יפרסם לכל מעלת אוהבו ולזה אמרו רבותינו ז"ל ואהבת את יי' אלהיך אהבתו על הבריות:
@93 **ודברת בם בשבתך בביתך ובלכתך בדרך.** למדנו מזה שזאת הפרשה צריך אדם לקרות כפי מה שהיא בזולת שום שנוי בשכבו ובקומו והנה מאמרו ודברת בם למדנו שהוא מחוייב כשיקרא את שמע שיהיה דבורו כאלו הדברים לא בדברים אחרים כי התעסקו בדברים אחרים יבלבלו כונתו באופן שלא יהיה כוונתו בם ומזה המקום למדנו שאין ראוי לו לרמוז בעיניו ולקרות בשפתותיו והדומה לזה בעת קרותו את שמע כי זהו כמו דבור בדברים אחרים עם קריאתו את שמע ולפי שאמ' בשבתך בביתך ובלכתך בדרך ולא אמר בבית ובדרך למדנו מזה שכאשר היה בשבתו בביתו או לכתו בדרך לצורך עצמו הו' חייב לזאת המצוה ואולם אם לא היה הלכת והשבת לו אבל היה לצורך עשיית מצוה לכבוד השם יתעלה הנה לא תדחה המצוה שהוא עוסק בה בעבור המצוה הזאת אלא אם היה יכול לעשות שתיהם כמו שהתבאר בשרשים הכוללים:
@93 **בשכבך ובקומך.** ידוע כי האדם יקרא שוכב בכל זמן שהוא שוכב על מטתו ויקרא קם בעת שהוא קם מעל המטה לבד ולפי שאלו הפעולות אין הכוונה בהם המציאות אבל העת שדרכו שיקרא בו זה כמו שזכרנו בשרשים הכוללים יהיה הרצון בשכבך בשעה שבני אדם שוכבי' ובקומך בשעה שבני אדם קמים והוא מבואר שזאת השעה הוא על הרוב בזמן שכיבה מעת צאת הכוכבים עד עלות השחר וזמן קימה הוא אחר זמן שכיבה והוא על הרוב אחר עליית השחר וכאלו הזמנים ראוי שתהיה קריאת זאת הפרשה אמנם לא יצא מגדר בשכבך אם היה זמן השעה זמן שכיבה על המעט או זמן קימה על המעט כי עדי הוא נכנס תחת גדר אמרו בשכבך ובקומך והנה זמן שכיבה על המעט יכנס מעת שקיעת החמה כי כבר ימצאו אנשים שוכבים אז לפי המנהג וכן ימשך גם כן לזאת הסבה עד הנץ החמה וזמן קימה על המעט ימשך עד עבור שתי שעות מן היום כי כבר ימצאו אנשים מעטים ינהגו לישן עד זה הזמן:
@94 **וקשרתם לאות על ידך.** הרצון בזה שיכתבם ואחר כך יקשרם כי הדברים לא יקשרו אך הנכתב ולפי שדקדק בכתיבה שתעשה על ידי מי שנכנס בגדר אלו המצוות באמרו וכתבתם על מזוזות ביתך ובשעריך למדנו מזה שלא יתכן שיכתבם כי אם מי שהוא בן תורה ולפי שהכתיבה הנהוגה היא בעור בהמה טהורה כי היא היותר שלמה בזה ראוי שתהיה הכתיבה באופן זה וראוי שיהיה בדיו באמרו ואני כותב על הספר בדיו וזה הנהוג גם כן מענין הכתיבה והנה מצאנו זה הלשון בעינו בפרשת קדש לי כל בכור שנאמר והיה לך לאות על ידך ובפרשת כי יבאך שנאמר והיה לך לאות על ידך ובפרשת והיה אם שמוע שנאמר וקשרתם לאות על ידכם למדנו מזה שבתפליחן של יד יכתוב אלו הארבע פרשיות ולפי שהסדור אשר להם בתורה הוא שתהיה ראשונה בפרשת קדש לי כל בכור ושנית פרשת והיה כי יביאך ושלישית פרשת שמע ורביעית רשת והיה אם שמוע ומצאנו שדקדקה התורה באלו העניינים שלא יומר בהם דבר מסדורם כמו שביארנו באמרו והיו הדברים האלה ידענו שהוא מחוייב שיהיה סדורם כן וכבר נלמד זה גם כן ממה שאמר בפרשה הראשונה והיה בלשון יחיד ובשמע והיה אם שמוע אמר בלשון רבים רוצה לומר שכבר אמר וקשרתם אותם ועוד כי בתפלין של ראש אמר בפרשת קדש לי ולזכרון לשון יחיד ובפרשת והיה כי יביאך אמר ולטוטפות לשון רבים ולפי שהקשירה לאלו הארבעה פרשיות היתה שתהיה לאות על ידו וכבר רצתה התורה שיהיו אלו הדברים על לבו הנה ידענו שהכונה בזה הוא שיהיו נקשרים למעלה מהזרוע שהוא אצל הלב והוא הפרק שעל הזרוע השמאלי וזהו ענין האו' לקושר והתפלין כי הוא לסימן שצריך שיהיו אלו הדברים על לבו תמיד ולפי שאין זה הענין אות כי אם למי שקושר התפלין כי לא יראוהו אחרים במקום ההוא לפי הנהוג מלבוש האדם שיכסה הפרק ההוא והנה יתבאר גם כן שהנחת תפילין של יד הוא בזה הפרק מן היד השמאלי לפי שנאמר וקשרתם לאות על ידיך. והנה הקשירה לפי הנהוג תעשה ביד הימיני ולזה יחוייב גם כן שיהיו מקום הנחת תפלין של יד אצל היד השמאלי כי לא יתכן שיקשור האדם ביד הימנית התפילין על היד ההיא בעצמה והנה אמר על ידך רוצה לומר אצל ידך והנה יקרא יד הזרוע עם היד ולזה יהיה זה היד במקום שתאנו אצל היד:
@94 **והיו לטוטפות בין עיניך.** רוצה לומר על המוח כאמרו לא תשימו קרחה בין עיניכם למת שהרצון בו על המוח כי הקרחה לא יתכן שתהיה בין העינים והנה הוא מבואר כי המוח היא בין העינים על המוח במקום השער תהיה הקרחה ושם לבד יתכן שיניח אלו התפילן ולזה אמר בפרשת קדש לי ולזכרון בין עיניך כי שם במוח ימצא כח הזוכר והנה הכוונה באמרו ולטוטפות לדבורים כענין אמרו ולא תטיף על בית ישחק ולפי שאמר בתפלין של יד לאו' שהוא לשון יחיד ואמנם בתפלין של ראש לטוטפות שהוא לשון רבים למדנו שהארבע פרשיות תהיינה יחד כסדרן בכרך אחד בתפלין של יד ואולם בתפלין של ראש תהיינה בד' בתים כי בפרשה השנית בא בה לשון רבים כמו שזכרנו ולזה הוא מבואר כי לא יהיה מהם בכרך אחד זולתי פרש' אחת ולזה יהיו בתפלין של ראש ד' בתים כדי שיהיו אלו הדבורי' נראים הבדלים זה מזה ולזה הקדים בכל הפרשיות האלו זכרון תפלין של יד קודם תפלין של ראש כי הם במקו' יותר נכבד לפי שהלב יותר נכבד מהמוח והנה היו הד' פרשיות בבית אחד בתפלין של יד שהן כנגד הלב והיו בד' בתים בתפלין של ראש כי בזה הישרה מה להשיג ייחוד הש' ית' עם רבוי הפעולות השופעו' מאתו וזה שהלב הוא התחלה לחי ומהחום הטבעי המשתלח ממנו במוח יסודרו מינים רבים מההרגש מצד המקבלים אשר שם וכן הענין בשם ית' כי רבוי פעולותיו לא יורו על רבוי בו ולפי שהלב הוא התחלה למה שישפע מהמוח מהחוש והתנועה הנה היה מהראוי שיהיו תפלין של יד קודמין לתפלין של ראש וזה ממה שיוסי גלוי ושלמות על שהרצון באמרו על ידך הוא כנגד הלב כמו שזכרנו ולפי שאמר בפרשת קדש לי והיה לך לאות על ידכה ובפרשת כי יביאך והיה לאות על ידך הנה למדנו שכל הווייתם המלאכותית צריך שתכוין לשם תפלין וכן העניין בקשירתם ולזה צריך שיהיה עבודם לשם תפלין וכתיבתן ועשייתן וקשירתן ולפי שאמ' במזוזה וכתבתם שהרצון בו הדב' הנהוג בענין הכתיבה למדנו כן הענין בתפלין והוא שתהיה הכתיבה באופן שתהיינה האותיות נכרות ולא ידמו לאות אחרת ותהיה כל אות נבדלת מהאחרת כי זהו מגדר הכתיבה ותהיינה גם כן הד' פרשיות לפי מה שהם בתורה ר"ל שהפתוחות תהיינה שם פתוחות והסתומות סתומות כי זה נהיה בתורה לענין בהכרח לא דבר רק הוא ובכלל הנה הפרשה פתוחה תורה מצד מה על הגמר העניין באופן מה והפרשה סתומה לא תורה על הגמר הענין באופן ההוא אבל הוא מורכב מן ההגמר וההקשר עם מה שאחריו ולזה היתה הפר' ההיא סתומה והנה להעיר על שאין השלמו' נמצא באלו הפרשיות אשר בתפלין לבדן ולא בפרשיות אשר במזוזה לבדם ואע"פ שיחדו בזה מבין שאר הפרשיות אשר בתורה כי השלמות האמתי לכלל התור' לבד תקנו רז"ל שיהיה ספר תורה נכתב בעור השלם ותפלין בחלק ממנו הנקרא קלף ומזוזה בחלק ממנו הנקרא דוכסוסתום להעיר על שאין אלו הפרשיות כי אם חלק מהתורה:
@95 **וכתבתם על מזוזות ביתך ובשעריך.** לפי שזה היה להזכיר דבר אלו הפרשיות אשר צונו לכתבם אצל מזוזות הבית והם פרשת שמע והיה אם שמוע למדנו שאין הרצון שיכתוב אצל כל אחד מזוזת הבית אבל הרצון באמרו אצל מזוזת כל בית ובית ולפי שזה דבר מונח מחוץ לבית למדנו שבמזוזה הימנית לו בהכנסו לבית יונה זה המכתב כי התורה בחרה הימין לכל הענינים לפי מה שהתבאר מפרטים דבי' בתורה והנה הבית יקרא סתם מה שהו' בית דירה:
@95 **ובשעריך.** ר"ל שערי ביתך שיש בהם מזוזה ולפי שאמר ביתך למדנו שאם היה בית מקדש פטור ממזוזה:
@96 **והיה כי יביאך יי'.** הזהירם שרב השבע והשלוה לא יסבב שישכחו הש' ית' שהוציאם ממצרים והנה זכר אלו הדברים בהדרגה כי הערים קודמי' לבנין הבתים שבהם ובפרט הערי' אשר להם חומה אשר יתאחדו בהם כל יושבי העיר כי בראשונה יהיה מקום העיר ותהיה מוקפת חומה אחר זה יבנה כל אחד מהמתישבים בעיר ההיא בית לעצמו והנה הבנין קודם לחציבת הבור וחיבת הבור קודם לנטיעת כרמים כי המי' יותר הכרחיים מהיין ולזה גם כן הקדים הכרמים לזתים כי היין יותר הכרחיי מהשמן:
@99 **את יי' אלהיך תירא.** וצוה בזה ליראה מה' ית' וענין היראה שנירא מלעבור על מצותיו לגודל מעלתו לרוממותו והוא מבואר שהיראה הזאת תשלם אחר שיושג הש' ית' כפי היכולת כי לא ירא האדם ממי שלא ידע מה הוא ולפי שההשגה ההיא תביא אל האהבה כמו שביארנו בפרשת שמע הנה יתחברו בשם יתעלה שתי אלו המדות כי למעלתו ורוממותו ייראו ממנו יראה עצומה ויאהבוהו אהבה נפלאה כמו שקדם:
@99 **ואותו תעבוד.** ידוע כי העבודה תהיה באחד משלשה פנים האופן האחד הוא שישרת העובד הנעבד במה שהוא לצורך נעבד וזאת העבודה לא תתכן בש' ית' כי הוא ברוך הוא בלתי צריך לדבר מנבראיו והאון השני הוא שיראה העוד שהוא עבד לנעבד במה שיצטרך העבד שישאל צרכיו מאדוניו להורות על שאינו שליט בלקיחת דבר מהם ולא יהיו לו כי אם מאדוניו שהוא שליט על הקנינים ההם ובזה האון השני יתכן שיעבוד האדם השם יתעלה רוצה לומר שיראה עצמו שהוא עבד לו ולזה ישאל צרכיו ממנו כמו שישאל העבד מאדוניו ולזה היה המאמר הזה צווי שנתפלל לפניו לבקשת צרכינו ובזה עוד תועלת להישיר האנשים שידעו כי כל הטובות באות מהשם יתע' והאופן השלישי הוא שיעשה העבד מה שיצוה האדון מזולת בטה שיהיה מה שיצוהו לצורך האדון או לצורך העבד וזה גם כן יתכן לאדם שיעבוד השם יתעלה ולפי זה העניין יהיה הרצון באמרו ואותו תעבד שכמו שהעבד עושה מצות אדניו כן תקים מצות השם יתעלה:
@99 **ובשמו תשבע.** צוה בזה להשבע בשם יתע' כאשר יביא ההכרח אל השבועה כי בזולת זה תהיה שוא כמו שהתבאר בפרשת יתרו הנה כמו שיחטא האדם או ישבע בשם יתעלה לשוא או לשקר כן יחטא אם ישבע לזולתו לעת צרכו אל השבועה כי זה יורה שהוא נותן האלמות והנצחות והקיום זולת השם יתעלה:
@100 **לא תלכו אחרי אלהים אחרים מאלהי העמים וגו'.** אמר זה לפי שכבר היה ידוע לשם יתעלה הכשל ישראל באלהי העמים ההם ולזה השתדל להצילם מזה והודיעם העונש הנפלא שימשך להם מהשם יתעלה אם יעשו זה:
@102 **לא תנסו את יי' אלהיכם באשר נסית' במסה.** הזהיר בזה שלא לנסות ושלא לשאול מופתי' רבים מהש' יתעלה אחר שנתבאר להם בנביאו שהוא נביא אמת ולזה אמר כאשר נסיתם במסה כי שם רצו לנסות הש' ית' לראות היש יי' בקרבם אם לא לא לצורך גדול כמו שבארנו בפר' בשלח:
@103 **שמור תשמרון את מצות יי' אלהיכם.** ביאר בזה כי בשמירת המצות התורה והעדות והחקים יתישרו אל הצלחת הנפש והוא אמרו למען ייטב לך וימשך להם גם כן מזה ירושת הארץ שהיא מישירה אל הטוב הזה כמו שביארנו בראש זאת הפרשה ולזה אמר ובאת וירשת את הארץ הטובה:
@106 **כי ישאלך בנך מחר לאמר מה העדות והחוקים וגומ'.** רמז בזה למצות פסח שהיה נאכל על מצות ומרורים ככל החקים והמשפטים שנתבארו בו שהוא בענינו שנוים רבים שיתעורר בעבורם הקטן לשאול מה הסבה בזה וכן הענין בכל השנויים שחדש לנו השם יתעלה לזכור דבר יציאת מצרים כאלו תאמר שלא נאכל שבעת ימים חמץ ושנשב שבעת ימים בסכות ומה שידמה לה:
@110 **ויצונו יי' לעשות את כל החקים האלה ליראה את יי' אלהינו.** ר"ל כי מזה נעמוד על הידיעה בעצם גבורות השם יתעלה ויביא זה אותנו ליראה ממנו:
@110 **טוב לנו כל הימים.** רמז בזה אל הטוב הנצחי אשר לא יכלה והוא הטוב הנפשי:
@110 **ולחיותנו ביום הזה.** רמז בזה אל החיים הגופיים הכלים והפוסקין:
@111 **וצדקה תהיה לנו.** ידוע כי צדקה הוא עשיית העושה מה שבחוקו לעשות והראוי לו כמו שביארנו באמרו והאמין ביי' ויחשבה לו צדקה והנה הרצון בזה כי זה הדבר הוא חוק עלינו וראוי לנו לפי היותר והצדק ונגמול טוב לנפשנו בשמרנו לעשות את כל זאת:
@111 **לפני יי' אלהינו.** ר"ל במקום אשר יבחר לשכן שמו שם כי שם יעשו הפסח והמועדים האחרים והמקום ההוא יתואר בזה התואר כמו שנזכר בפרשת ראה אנכי במקומות רבים:
@112 **ונשל.** והשליך:
@113 **לא תכרות להם ברית ולא תחונם.** הזהיר בזה מחמול עליהם והסבה בז פן יחטיאו אותנו ולזה הזהירתנו במה שיבא שלא נחיה כל נשמה באלו השבעה גוים ואף על פי שכבר רצה השם יתעלה שיקראו להם לשלום חלה כמו שנתב' בפרשת שופטי' הנה הקשה את רוחם ואמץ את לבבם למן החרימם להשגח' על ישראל כמו שנזכר בספר שופטים ולזאת הסבה אמר בפרשת ואלה המשפטים שלא ישבו בארצנו פן יחטיאו אותנו לו:
@114 **ולא תתחתן בם בתך לא תתל לבנו ובתו לא תקח לבנך כי יסיר את בנך מאחרי וגו'.** ידוע כי החתונות לא יתכן לאלו וזה מבואר ממה שנזכר בשפחה כנענית בפרשת משפטים שבניהם אינם למי שהוליד אותם והוא העבד העברי אבל הם בניה והם עבדים כאמרו האשה וילדיה תהיה לאדוניה ולהורות שלא יהיה עמה חתונות לישראל אמר לא יומתו כי לא חופשה בשפחה חרופה ואם תענין בשפחה כנענית בן שנכנסה בקצת מצות התורה כ"ש באלו שלא נכנסו בגדר מצות התורה כלל ואמנם ר"ל באמרו לא תתחתן בם שלא יעשה עמהם דבר דומה לחתונות והוא שתהיה מיוחדת לו כמנהג האשה עם בעלה והוא מבואר מזה שאם נתן ישראל בתו לאחד מאלו הגוים הנה ולדה כשר כמוה ואולם מנע זה כי הגוי שהוליד אותו יסיר הבן ההוא שילדה בה ישר' מאחרי השם יתעלה וכ"ש שימנע מנתינת בן ישראל לנכריה כי הוא יוליד בנים לע"ז כי בניהם הם כמוה ולזה אמר ועבדו אלהים אחרים ר"ל זרע הבן וזרע הבת והנה לא הזהירה תורה אלא דרך חתנות אבל אם באו עליה שלא כדרך חתנות אינו לוקה מן התורה אך נתבאר בסוף פרש' בלק שקנאין פוגעים בו אם מצאוהו בשעת מעשה כמו שעשה פנחס בדבר זמרי וכזבי:
@116 **כי אם כה תעשה להם מזבחותיהם תתוצון וגומ'.** ר"ל שלא תעשו עמהם מה שיביא אתכם לעבודה זרה כמו שנזכר בענין החתנות אבל השתדלו עכ"פ להסיר הע"ז מארצכם כדי שלא תהיו נמשכים אחריה ולזה צוה לנתוץ מזבחותיהם ולגדע אשריהם ולשרו פסיליהם:
@117 **כי עם קדוש אתה ליי' אלהיך וגו'.** ר"ל אין ראוי שתתגאל אתה בכל אלו הפחיתיות ואלו השיקוצים בשאר האומות כי כבר נבדלת משאר האומות בזאת התורה הנפלאה ונתקדשת בה ובה נהיית לשם יתעלה לעם סגלה מכל העמים וביאר להם כי לא מפני שהם עם רב בחר בהם השם יתעלה להשענו שבחזקם ינצחו שאר האומות אך הענין הוא בהפך כי ישראל הם המעט מכל העמים אך מאהבת השם יתע' את ישר' ומצד בריתו עם האבו' הוציאם ממצרי' ביד חזקה לקרבם לעבודתו כדי שיהיו ראויים אל הטוב שייעד הש' יתע' לאבותיהם לתת לזרעם:
@120 **וידעת כי יי' הוא האלהים.** ר"ל כי השם יתעלה הוא המשגיח בך ומנהיג אותך הוא האלהים במוחלט ר"ל שהוא מנהיג כל הנמצאות:
@120 **האל הנאמן.** ר"ל האל נאמן בהבטחתו:
@120 **שומר הברית והחסד לאוהביו ולשומרי מצותיו לאלף דור.** הנה מה שייעד השם יתע' מהטוב הוא חסד בעת ההוא אך קיומו היעוד הוא כמו חק על השם יעלה והוא יקיים אותו לדורות רבים והנה קרא אהביו הדביקי' בו ומשיגים אותו כפי מה שאפשר ושומרי מצותיו הם מקיימי מצות השם יתע' והנה שמירת מצותיו תביא לאהבה את יי' יתעלה כי יהיו דרך להשגתו יתעלה ואהבתו גם כן סבה לשמיר' מצותי ובאר בזה כי הטוב המסודר לאדם מצד ההשגחה הפרטית ימשך לזרעו אחריו דורות רבים רבים מלמנות וכבר יתבאר כי זה הברית שכרת השם יתעלה עם האבות לא יפר לעולם ולזה אמר שישמרם השם יתעלה תמיד מכליון כמו שקדם או ירצה בזה שהש' יתעלה ממתין הברית והחסד לאוהביו לאלף דור וזה שכבר ייעד זה הטוב לאברהם וקיימו לו אחר זמן ארוך באופן יותר שלם במה שהשלים הש' יתע' זרע ישראל וקרבם לעבודתו ויהיה אמרו שומר הברית והחסד מענין אמרו ואביו שמר את הדבר והנה הבאור הזה הוא נאות בזה המקום לפי מה שאחשוב:
@121 **ומשלם לשונאיו אל פניו להאבידו.** ר"ל כי הטוב שייעד לשונאיו לא יאחר הגעתו אבל יגיעהו להם תכף להאביד שונאיו במה שיקרה להם מההפסד והכליון אחר הגעת הטוב ההוא להם כמו שקרה לאלו האומות כבר אבדו קודם הגעת הטוב בישראל וגם הטוב ההוא שמור עדין לישראל כי לא הגיע להם כל הטוב שנשבע השם יתע' לאברהם בימי יהושע כי כבר נתן לו השם יתעלה עשר אומות ולא השחית יהושע כי אם קצת השבעה מהם ולזה יתאמת שזה הטוב שמור לישראל לאלף דור וכאשר ישלם הטוב ההוא יסודר הענין בדרך שלא תקרה עוד מלחמה כי אל יהפוך השם יתעלה אל העמים שפה ברורה לקרוא כלם בשם יי' ולעבדו שכם אחד ובזה יתבאר כי להטיב לישראל היה כשהמתין להם השם יתעלה הברית והחסד לדורות רבים:
@122 **ושמרת את המצוה ואת החקים ואת המשפטים וגו'.** ר"ל כי הוא ראוי שישמור את המצוה ואת החקים ואת המשפטים אשר אנכי מצוך היום לעשותם. כי זה יהיה סבה להביא הטוב ולהתמידו לך הנה זה מה שצריך לבאר בזאת הפרשה.

@1 והתועלות המגיעים ממנה הם תשע עשרה:
@1 **התועלת** הראשון הוא הודיע שהמתפלל צרך שישתדל תחלה לסדר שבחי השם יתע' ולהשיג אותו כפי היכולת ואחר זה בהיותו דבק בשם יתעלה יאות לו להתפלל ולבקש ממנו מה שירצה הלא תראה כי משה רבינו עליו השלום אף על פי שהיה באופן מהשלמות שהיה תמיד עם השם יתעלה עד שכבר היה מתנבא בכל עת שירצה כאמרו. עמדו ואשמעה מה יצוה יי' לכם הנה עם כל זה כשרצה להתפלל לשם יתעלה לבקש ממנו שיעבור את הירדן ויראה את הארץ ספר תחלה שבחי הש' יתעלה במה שהורה על השגחתו יתעלה בשעור האפשרי ואחר זה בקש בקשתו ולזה תקנו רבותינו זכרונ' לברכה שיסמך אדם גאולה לתפלה כדי שתהיה ענין התפילה אחר סדור השבחים הנפלאים הנכללים בברכות ק"ש ובק"ש ולזה אמ' והתענג על יי' ויתן לך משאלות לב כי מי שישיג השם יתעלה ההשגה האפשרי' לו הוא מתענג עליו תענוג נפלא ולזה תהיה אז תפילתו נשמעת לדבקות ההשגחה האלהית בו וזה גם כן מה שאמר איוב אם על שדי יתענג יקרא אלוה בכל עת:
@1 **התועלת** השני הוא להודיע כי גודל השם יתעלה וידו החזקה הוא בלי אפשר שיושג מנו כי אם שעור מעט ביחס אל מה שהוא בעצמותו הלא תראה כי משה רבי' עליו השלום עם עלותו לזאת המעלה הנפלאה שזכר בה מן החכמה והנבואה אמר שלא השיג מזה כי אם שעור מעט ולזה אמר שהשם יתעלה התחיל להראותו זה:
@1 **התועלת** השלישי הוא להודיע כי השלמי' אינם בוחרי' אלו החיים הגופיים כי אם לתכלית שיוסיפו בשלמות הנפש ולזה נתן משה הסבה במה בקש מהשם יתעל שיתנהו לעבור את הירדן ולראות את הארץ שכבר התחיל השם יתעלה להראותו גדלו וידו החזקה ולזה בחר שיכנס לארץ שהיא נבחרת אל שישפע בה השפע האלהי כדי שיוסיף שלמות על שלמותו ויראהו השם יתעלה שם מגדלו וידו החזקה יותר מה שהראה לו מזה עד עתה ליתרון הכנת הארץ ההיא ולא בחר זה כדי לאכול מפירות הארץ כמו שחשבו הסכלים:
@1 **התועלת** הרביעי הוא להודיע שראוי לאדם שלא יתפאר בחכמתו והשגתו לומר שכבר השיג מזה שעוד רב אך ראוי שיחשוב עצמו חסר מאד כי בזה יוסיף זריזות לבקש השלמות הלא תראה כי משה רבינו עם חוזק השגתו חשב עצמו חסר מאד עד שאמ' כי הוא בתחלת דרך השגת השלמו' לשערו שכבר יתכן שיוסיף שלמות על שלמותו ולזה אמר יי' אלהים אתה החלות להראות את עבדך וגומ':
@1 **התועלת** החמישי הוא להודיע שמה שבחר השם יתע' לתת לבני ישראל את האר היה מצד יתרון הכתה אל השגת השלמות האנושי ולזה סמך משה לזכירתו טוב ארץ ישראל על שאר הארצות וטוב הר בית המקדש על כל ארץ ישראל ענין אשר התחילו להשיג גודל השם יתעלה וידו החזקה להעיר שטוב הארץ ההיא יהיה כלי לו להוסיף על זה השלמות:
@1 **התועלת** הששי הוא בדעות הוא להודיע עוצם ההבדל שיש בין השם יתעלה ובין שאר הנבדלים כי אין בהם מי שיהיה מנהיג בכללות בשמים ובארץ זולתו וזה כי הם ואם יש לאחד מהם הנהגה מה בשמי' ובארץ הנה היא חלקית והיא עלולה מהשם יתעלה ואין בהם גם כן מי שיעשה כמעשה השם יתעלה וכגבורתו כי מעשיהם חסרים מאד כמו שביארנו בחמישי מספר מלחמו' יי' כי אין התכלית מגיע מהם אלא במעשי' רבים יצטרפו אל מעשיהם ואולם מעשה השם יתעלה הם שלמי' בעצמם בתכלית מה שאשר וכן אין יחס בין הגבורו' המתחדשות מהם ובין גבורות השם יתעלה וזה שהגבורות הנפלאות ואם יקרה שיתחדשו מהם על צד ההשגחה הכוללת להביא אל שתנצח אומה אומה אחרת חזקה ממנה כמו שנזכר בבני עמון ומואב הנה זה לא יהיה רק בעת מוגבל לפי הסדור השופע מהשגחת זאת האומה בעת ההיא וזה גם כן ששזכרנו מצד מעשיה' וגבורותיהם לא שיעשו באמצעות מה שיושפע להם מהשם יתעלה כי מאתו הכל והוא עשאם ומאתו שופע תמיד מה שיסודר מהם ואולם השם יתעלה יעשה הגבורות בכל עת שימצא ראוי להם לא בעת זולת עת ולזה גם כן אמר כי מי גוי גדול אשר לו אלהים קרובים ואליו כיי' אלהינו בכל קראנו אליו כי גוים שהם תחת ממשלת הכוכבים לא ישיגו עזר מהם כי אם בעתים מיוחדי' לפי מה הוגבל להם אז אמנם השם יתעלה יגיעו ממנו עזר לנו בכל עת שנקרא אליו באופן ראוי רוצה לומר כשנישיר עצמנו אל שנהיה ראויים שתדבק השגחתו הפרטית בנו ולזאת הסבה גם כן אמר ופן תשא עיניך השמימה וראית את השמש ואת הירח וגו'. אשר חלק יי' אלהיך לכל העמים וגו'. ואתכם לקח יי' וגומ'. ביאר שענין שאר האומות הוא מסודר מהמערכת אשר לכוכבים ואמנם ישראל הם תחת השגחת השם יתעלה הפרטית:
@1 **התועלת** השביעי הוא במדות והוא להודיע שהוא ראוי למי שישיגהו עונש מהשם יתעלה על מריו שיראה שהוא מרגיש שעור מה שאבד ממנו כי בזה תועלת ללקיחת המוסר כי מי שלא ירגיש שהוכה על מריו לא יקבל מוסר כמו שאמר הנביא על מה תוכו עוד תוסיפו סרה וגומ' ולזה תמצא שמשה הראה שהוא מרגיש בשעור מה שאבד ממנו בשלא הסכים השם יתעלה שיעבור את הירדן כדי להקנותו זאת המדה החשובה:
@1 **התועלת** השמיני הוא בדעות והוא להודיע שלא זכה משה לזאת המעלה העליונה מהנבואה מצד יתרון הכנתו הטבעית לקבל שפע הנבואה שאם היה זה כן לא היה ראוי שישיב השם יתעלה למשה על בקשתו זאת רב לך כי בודאי היה מוסיף שלמות בנבואה לפי זאת ההנחה אם היה בא לארץ ישראל מני יתרון הכנתה לנבואה לזה הוא מבואר שלא השיג משה רבינו זאת המעלה הנפלאה מהנבואה מצד יתרון הכנתו על האנשים כולם כי כמו זאת ההכנה יתכן שימצא לזולתו כי זה דרך האפשר במין כמו שהתבאר בטבעיות וכבר יתבאר במה שיבא מדברי התורה הקדושה שלא יהיה שם נביא תורה זולת משה עליו השלום ולזה הוא מבואר כי עוצם מעלת נבואה משה להנתן זאת התורה האלהית על ידו היה מהשם יתעלה על צד המופת והפלא. כמו שהיה עני מעמד הר סיני על דרך הנפלאות ומפני זה ענה השם יתעלה למשה על שאלתו זאת רב לך רוצה לומר שיתרון הכנת הארץ לא יוכל להוסיף על שלמותך בנבואה כי לא היה זה השלמות לך מצד הכנתך כי אני שמתיו לך עודף על שלמות כל בעל הכנה ולזה ראוי שתדע כי מה שאמרנו בפרשת בלק שכבר יקום נביא בישראל ובשאר האומות כמשה והוא מלך המשיח אשר אנחנו מקוים אין הרצון בזה שיהיה נביא תורה כי זה בלתי אפשר ואינו דרך הנבואה במה שהיא נבואה שתודיע נימוס תוריי אלהי אם לא על דרך המופת כמו שהיה הענין בנבואת משה אך הרצון בזה שיהיה כמוהו אל למעלה ממנו בעניינים הה הנזכרים שם רוצה לומר חדוש האותות והמופתים ויתר העניינים שהמשיך למה שאמר ולא קם נביא עוד בישראל כמשה:
@1 **התועלת** התשיעי הוא במדות והוא לזרז האנשים שישתדלו לראות כל הדברים שיוכלו לראות כדי שיכירו בזה חכמת השם יתעלה שברא אלו הענינים ולזה תמצא כי משה בקש שאם לא ירצה השם יתעלה שיעבור הירדן יסכים שיראה הארץ בכללה כדי שיעמוד על סבות מעלות הארץ ההיא מצד מצבה ומצד מקומה מהיישוב ולזה יהיה רצון באמרו אעברה נא ואראה את הארץ אעברה נא או אראה וכבר יעיר שהכוונה היא כן שכבר אמר השם יתעלה למשה עלה ראש הפסגה ושא עיניך וגומ' והנה מצאנו שזאת התכונה היתה חזקה במשה ולזה אמר אסורה נא ואראה את המראה הגדול הזה מדוע לא יבער הסנה כמו שביארנו בפרשת ואלה שמות:
@1 **התועלת** העשירי הוא במדות והוא להודיע שהוא ראוי למנהיג שישתדל בהגעת הטוב האפשרי למונהגי' ממנו ולזה תמצא לפי מה שיראה מתשובת השם יתעלה למשה על זאת הבקשה שבקש שיעבור את הירדן כדי שינחיל הארץ לישראל ביותר שלם שבפנים כי במעט זמן היה מנחילה להם אם היה עובר שם לפי מה שיראה מהמלחמות שעשה משה במעט זמן ולזה ענהו השם יתעלה שיצוה את יהושע איך יתנהג בפועל הנהגת הארץ לישראל ויחזקהו ויאמצהו כי הוא ינחיל הארץ לישראל למדנו מזה כי משה היה מבקש שהוא ינחיל הארץ לישראל מצד שערו שעל ידו יהיה נעשה באופן שלם וכדי שיהיה יהושע בזה תמורת משה לפי מה שאפשר ויתפוס בזה משה לשערו שהוא ישתדל בזה האופן השלם רצה השם יתעלה שיישיר משה את יהושע בכל מה שיעשהו באופן שתשלם לו הנחלת הארץ לישראל באופן שלם:
@1 **התועלת** האחת עשרה הוא בדעות והוא להודיע שהתורה השלמה שנתנה השם יתעלה לנו על יד משה היא מישרת אל השגת החיים הנצחיים והם חיי הנפש וימשך ממנה עוד תועלת בהצלחות הגופיות מצד מה שהם הישרה ומביא להצלחת הנפש ולזה אמר ועתה ישראל שמע את החקים ואל המשפטים אשר אנכי מצוה אתכם לעשות למען תחיון ובאתם וירשתם את וגומ' והוא מבואר שאמרו למען תחיון אין הרצון בו החיים הגופיים כי לא יצטרך לומר אלא למען תבואו ותרשו את הארץ כי ידענו שלא יירשו את הארץ והם מתים אבל רצה באמרו למען תחיון החיים האמתיים הבלתי פוסקים והם חיי הנפש ויעד עם זה שכבר תהיה סבה לירושת הארץ ההיא שהיא הצלחת גופיית והיא מישרת גם כן אל ההצלחה הנפשיית כמו שזכרנו באלו התועלות ולזה גם כן כוון באמרו בפרשת אחרי מות ושמרתם את חוקותי ואת משפטי אשר יעשה אותם האד' וחי בהם רוצה לומר חיי הנפש כי הם החיים האנושיים וכבר התבאר מדברינו בתועלות המצות כי התורה היא המישרת בתכלית מה שאפשר אל אלו החיים הנצחיים שהם חיי הנפש ולזה כוון פה במה שאשמר ושמרתם את חקותי ואת משפטי אשר אנכי מצוך היום אשר ייטב לך ולבניך אחריך למען תאריך ימי' על האדמה. כיון באמרו אשר ייטב לך למה שהוא טוב אנושי והוא הטוב הנפשיי ולזה הבדיל בינו ובין הטוב הגופיי ואמר למען תאריכו ימי' על האדמה להעיר שזה התועלת אינו ממין התועלת הראשון אלא שהוא יגיע מן התורה בשנית ואולם בעצמות וראשונה יגיע ממנה הטוב האמתי שהוא הטוב הנפשיי:
@1 **התועלת** השתים עשרה במצות והוא מה שהוזהרנו שלא להוסיף על מצוות התורה ושלא לגרוע מהם באופן שימשך מזה הפסד מה בשמירת התורה והמצות והוא אמרו לא תוספיו על הדבר אשר אנכי מצוה אתכם ולא תגרעו ממנו לשמור את מצות יי' אלהיכם והתועלת באלו האזהרות מבואר כי לולי זה תפסד כוונת התורה בכללה וצוני לומר אם היה זה השער פתוח להוסיף על מצות התורה או לגרוע מהם וזה ממה שאינו צריך אל ביאור עם מה שקדם לנו מהדברים בזה הספר:
@1 **התועלת** השלש עשרה הוא להודיע עוצם השגחת השם יתעלה בישראל עד שכבר זכר שלא מת אחד מהם זולת אשר מתו על דבר פעור וכבר יה ראוי לפי המנהג הטבעי בעם גדול כזה שימותו בכל יום רבים מהם והיה זה כן כי כבר הבטיחם השם יתעלה שזה הדור יירשו הארץ וכמו שהמית במדבר הדור הקודם על מרים כן רצה להשאיר אלו כדי שיירשו כולם את הארץ ולזה זכר כי לולי עונם לא היה אחד מהם מת והעד על זה כי האנשים לבד אשר נכשלו בעון פעור מתו ולא מת זולתם כאמרו ואתם הדבקים ביי' אלהיכם חיים כלכם היום:
@1 **התועלת** הארבע עשרה הוא להעיר על עוצם החכמה והבינה שיישירו המצו' התלויו' בארץ שיחשב בתחלת העיון שאין בהם תועלת והם המצות אשר בקרבנות ובטומאות ובטהרות ומתנות כהונה ולויה ולזה אמר ראה למדתי אתכם חקים ומשפטים כאשר צוני יי' אלהי לעשות כן בקרב הארץ וגומ' כי היא חכמתכם ובינתכם לעיני הגוים וכבר ביארנו אנחנו במה שקדם אופן החכמה והבינה אשר יישירו אלו המצות ובכלל הנה תורתנו תיוחד משאר התורות והנימוסים שהיו לשאר האומות כי תורתנו אין בה דבר לא יגזרהו היושר והבינה ולזה היה זה הנימוס האלהי מושך האנשים מצד עצמותו אל שיתנהגו בו ואמנם נימוסי שאר האומות אינם כן כי הם מסודרים לפי יושר וחכמה והם נימוסי' זרים מטבעי האנשים ויתנהגו בהם האנשים על צד ההכרח מצד אימת המלכות ואימת הטלת העונש לא מצד עמצותם:
@1 **התועלת** החמש עשרה הוא מה שצונו לזכור ענין מעמד הר סיני והדברים ששמענו שם מפי הגבורה הם עשרת הדברים אשר יקיפו באופן מה שבכל המצות התוריות ועניין זה הזכרון הוא שנודיע זה לבנינו ולבני בנינו דור אחר דור למען יתפרסם זה לכולם וישמרו מצוות התורה וילמדו ליראה את השם הנכבד והנורא וידענו כי לא ראו שם כל תמונה ולזה ירחיקו התמונה מהשם יתעלה ויהיו נשמרים מעשות פסל ותמונה ומנתינת אלהות לזולת השם יתעלה כמו שביאר האזהרה בזה הדבור השני מעשרת הדברות:
@1 **התועלת** השש עשרה הוא במצות. והוא להודיע שכמו שהאדם חייב ללמוד את בנו כמו שכתוב ושננתם לבניך כן הוא חייב ללמוד את בן בנו כמו שנאמר והודעתם לבניך ולבני בניך:
@1 **התועלת** השביעי עשרה הוא להודיע שהתורה השתדלה לפי מה שאפשר לשמור את ישראל שלא יפלו ברע אשר נפלו בו מפני עבדם עבודה זרה ולזה הודיעם השם יתעלה ענין הגליות אשר יפלו בהם בהמשכם לעבודה זרה ולזה לא נמנעו ישראל עם כל זה מהמשך לעבודה זרה ונפלו ברע אשר יעדה התורה על זה לא נפל דבר:
@1 **התועלת** השמנה עשרה הוא להודיע שכבר ימשך מההשגחה הפרטית ענין דומה למה שנמשך מההשגחה הכוללת רוצה לומר שכמו שימשך לאדם מההצלחה מההשגח' הכוללת שיושגחו בה הוא וזרעו זמן ארוך מאד ג"כ יקרה זה מצד ההשגחה הפרטית כאשר היתה שלמה ולזה תמצא שספר כי מפני השגחת השם יתעלה על האבות יושגחו זרעם אחריהם תמיד בדרך שלא יכלו ומפני זאת ההשגחה השגיח השם יתעלה על ישראל בהיותם במצרים והוציאם משם באותות ומופתים נפלאים לקרבם לעבודתו כדי שיהיו ראויים לירושת הארץ ולזאת הסבה נתן להם התורה התמימה ונתנה להם בזה האופן הנפלא שהיה במעמד הר סיני להביאם על כל פנים אל שימשכו אחר תורתו השלמה כדי שיזכו שתנתן להם הארץ שנשבע השם יתע' לאבותינו לתתה לזרעם:
@1 **התועלת** התשע עשרה הוא בדעות. והוא להודיע כי מי שהוא אלהי השמים הוא אלהי הארץ אין שם שני אלוהות יהיה האחד אלהי השמים והאחד אלהי הארץ כמו שהאמינו המאמינים בשניות וזאת הידיעה קנו ישראל מענייני המופתים הנפלאים שעשה השם יתעלה שלא ימשך ענינם מצד הטבע אשר באו באלו הדברים השפלים כמו שאמר אתה הראית לדעת כי יי' הוא האלהים אין עוד מלבדו כמו שביארנו ואם אמר אומר הנה זה לא יתן האמת בזה על כל פנים כי אולי יאמר אומר כי אלהי הארץ ינהיג הארץ לפי הטבע וכשיצטרך ישנה הוא מנהג הטבע אמרנו לו כי משה לא היה מדבר לסכלים כי כבר היו זקני ישראל והוא מבואר שלא יוכלו להניח שאלהי השמים יהיה נבדל מאלהי הארץ בדרך שיהיו שנים כי הם רואים הרבה מהנהגת ענייני הארץ מסודרת מצד השמים ולזה יחוייב שיהיה מי שיכול לשנות זה הסידור אשר בארץ עליון על כל השמים ואין צריך לומר שהוא עליון על הארץ ומזה התבאר כי מעניין המופתים נעמוד על שבכאן מנהיג אחד הגלגלים בכללם:
@62 והנה התועלות המגיעות ממנה הם י"א.
@62 **התועלת** הראשון להודיע שכל מצות התורה נתנו במעמד הר סיני בזמן הר סיני אך לא נתחדש אחר זה בתורה דבר שלא נכלל במה שנזכר שם ואולם אלו הדברים ששמע אז סדר משה לבני ישראל בעבר הירדן בגאי מול בית פעור ולזה אמר וזאת התורה אשר שם משה לפני בני ישראל. אשר דבר משה אל בני ישראל בצאתם ממצרים:
@62 **התועלת** השני הוא להעיר שפנת התורה הוא להאמין בשם יתעלה ולהרחיק עובדה זרה לזה הזהיר משה על שתי אלו המצות ממה שקדם מזאת הפרשה שנכלל בה הצווי על האמונה שהשם יתעלה הוא אלהי השמים ואלהי הארץ והאזהרה מעשיית פסל ומסכה ומעבוד זולתו יתעלה וביאר העונש הנפלא שימשך בזה מענין ירושת הארץ ואחר הפסיק הענין ושב להתחיל זכרון עשרת הדברים בכללם והרבה ממצות התורה שנתנו במעמד הר סיני ואם לא נזכרו קצתם כי אם בזה המקום:
@62 **התועלת** השלישי הוא במצות והוא להודיע שכל אדם מחוייב ללמוד תורה ואף על פי שיוכל לעשות מצותיה בזולת למידת התורה בשישאל זה ליודעי התורה וזה למדנו מאמרו ולמדתם אותם ושמרתם לעשותם ולא אמר ולמדתם אותם למען תעשו אותם אך הלמידה מצוה והמעשה מצוה והיה זה כן כי הלמידה מביאה לעמוד על כוונת התורה יותר מהמעשה עם שהלמידה ימצא בה תועלת להביא אל המעשה ולזה הוא מבואר שגדול שכר תלמוד תורה משכר עשיית מצוה מהמצות:
@62 **התועלת** הרביעי הוא להודיע שלא נתנה התורה לדור ההוא לבד אך לכל הדורות הנמשכים אליהם. ולזה אמר לא את אבותינו כרת את הברית הזאת וגומ'. ואמר מי יתן והיה לבבם זה להם ליראה אותי ולשמור את כל מצותי כל הימים ואמר אשר אנכי מצוך אתה ובנך ובן בנך כל ימי חייך כי זה כולו יורה שהתורה נתנה לדורות הנמשכים לאין תכלית וזאת היא מפנות הגדולות שבפנות התורה והיא מחוייבת עוד מצד העיון כי לא יתכן שיוחס לשם יתעלה שנוי רצון כמו שיתבאר במקומותיו וכבר אמר הנביא גם כן אני יי' לא שניתי:
@62 **התועלת** החמישי הוא במצות והוא להודיע שהנשים מחוייבות לקדוש היום וזה למדנו מאמרו שמור את יום השבת לקדשו כמו שביארנו בבאורנו בזה הפסוק:
@62 **התועלת** הששי הוא להודיע שהתורה כבר תצוה במצוה אחת לתועלת יותר מאחר וזה ממה שיפתח לנו השער לעמוד על הרבה מכוונות מצות התורה כמו שיתבאר מדברינו בזה הספר וזה למדנו ממה שנתן בזה המקום הסבה במצות שבת לזכור ענין יציאת מצרים ובפרשת יתרו נתן הסבה בה לזכור דבר חודש העולם:
@62 **התועלת** השביעי הוא להודיע שלולי יראת ישראל מהדברים הנפלאים שבמעמד הר סיני כבר היו ישראל שומעים כל התורה מפי הגבורה כי הקול הנפלא ההוא לא פסק בעת שעמדו העם מרחוק ובקשו ממשה שישמע הוא הדברים ויביאם אליהם ואל ידבר עמם אלהים פן ימותו וזה ממה שיוסיף אמות להם על שהתורה בכללה הוא מה' יתעלה ואף על פי שהיה משה באופן מהמעלה שהיה ראוי שיאמינו בו ישראל הנה רצה השם יתעלה בזה לפי שזאת התורה כוון בה שתהיה נצחית ושלא יאמן נביא שיאמר דבר בסתירה ממנה ואלו לא היתה לישראל אמונה בה אם לא מפי משה לא יתכן זה כי יאמרו למה נאמין יותר במשה ממה שנאמין בזה הנביא אשר נתן לנו אותות ומופתים ואולם עתה יתכן זה כי יאמרו לא נוכל להאמין מי שיאמר דבר מכחיש מה שראינו בעינינו ולזאת הסבה גם כן רצה השם יתע' שיהיה מכתב הלוחות מעשה השם יתעלה לא במלאכה:
@62 **התועלת** השמיני הוא באזהרות והוא מה שהזהרנו שלא נתאוה..:
@62 חסר כאן ובכל העתקות שהיו לפנינו.:
@62 **התועלת** התשיעי הוא בדעות והוא להודיע כי השם יתעלה לא יגזור בענינים הבחיריים דבר על דרך החיוב אבל יניחהו אפשרים אלא אם היה זה על דרך המופת וזה יהיה בפרט מה ובעת מה לא תמיד וכבר למדנו זה ממה שאמ' מי יתן והיה לבבם זה להם ליראה אותי כמו שביארנו בביאור דברי זאת הפרשה:
@62 **התועלת** העשירי הוא ללמדנו שכבר היה מהשם יתע' שיהיה משה פורש מן האשה מצד שקדו עם השם יתעלה תמיד ודבר זה למדנו מאמרו לך אמור להם שובו לכם לאהליכם ואתה פה עמוד עמדי:
@62 **התועלת** האחת עשרה הוא להודיע כי השם יתעלה מסר המצוה וחוקיה ומשפטי' למשה ופירושיה ודקדוקיה וצוהו שילמדה בזה האופן לישראל וזה לאות כי הוא ילמד לישראל דבר לא נכתב בתורה כמו שביארנו שאם לא היה אומר לישראל זולת הכתוב בתורה לא היה אור אשר תלמדם אבל יאמר אשר תגיד להם או תאמר להם ואולם אומר אשר תלמדם כי הוא יבאר להם לשון דברי התורה באופן שיעמדו על כוונותיה:
@90 **שמע ישראל יי' אלהינו יי' אחד עד סוף הפרשה:**
@90 והתועלות הם י"ט:
@90 **התועלת** הראשון הוא במצות והוא מה שצונו להאמין שהשם יתע' הוא משגיח בו עדת ההולכים בתורתו ותועלת זאת המצוה הוא רב בדעות והוא עם זה מהגדולות שבפנו' התור' וכבר ביארנו אמות זה השרש מצד העיון והתרנו כל הספקות הנופלות בו ברביעי מספר מלחמות ה' ובביאורינו לספר איוב:
@90 **התועלת** השני במצות והוא מה שצונו להאמין כי יי' אחד אחדות אמתי לא ישתתף לו בו זולתו וכבר ביארנו אמות זה השרש ושהוא ראוי שיתואר השם יתעלה בשני אלו השמות שזכרה בה התורה בחמישי ממ"י ובביאורנו למה שאחר הטבע:
@90 **התועלת** השלישי הוא במצות והוא מה שצונו לאהבה השם יתעלה בזה האופן הנפלא שיקל לנו כבוד המות לכבודו יתעלה והתועלות בזאת המצוה מבואר כי זה ממה שיביא בתכלית מה שאפשר לקנין השלמות האנושי וההצלחה הנפשיית אשר אין הצלחה זולתה כמו שביארנו בבאור זאת הפרשה:
@90 **התועלת** הרביעי הוא במצות והוא מה שצונו ללמד אלו הדברים שהם פנות התורה כדי שיתישבו אלו הפנות והאמונות האמתיות בלבם ויגדלו עליהם וכן צוה זה בעשרת באמרו והודעתם לבניך ולבני בניך ואמר בכללות למען ילמדון ליראה וגו'. ואת בניהם ילמדון וזה מקיף בכל מצות התורה כי כבר היו שומעין אותם כולם מפי השם יתעלה לולי יראתם מהאש ולזה כשלמדו' ממשה חוייבו ללמדם לבניהם דור אחר דור:
@90 **התועלת** החמישי הוא במצות והוא מה שצונו לקרא פרשת שמע שתי פעמים ביום. ר"ל בשכבנו ובקומנו כי בה זכירת אלו המצות שזכרנו שהם פנות התורה ואמנם היתה הקריאה באלו העתים כי אלו העתים יורו על שיש לגלגלי' תנועה כשיעוין אז בכוכבי לכת ובכוכבים הקיימי' שיראו בו כוכי לכת מתרחקים מהכוכבים הקיימי' שהם קרובי' אליהם או הפך או יעויין בשמש עם הנץ החמש כי ראה שמקום זריחתו ביום האחר וזה יורה על שהשמש מתנועע לא הארץ כמו שחשבו קצת הקודמים ולזה הוא מבואר שאלו העתים יורו שיש לגלגלים תנועות מתחלפות ויצטרכו מפני זה אל מניע קודם להם וזה יביא בהכרח להאמין שיש שם אלוה אחד שיסודרו ממנו כל אלו התנועות אשר ישלם בכללם זה המציאות השפל:
@90 **התועלת** הששי במצות והוא מה שצונו להניח תפילין על הפרק שאחר הזרוע כנגד הלב והנה נכללו בהם ד' פרשיות והם קדש לי כל בכור והיה כי יביאך שהם מזכירות ענין הנפלאות שהיו ביציאת מצרים אשר יישירו לאמונת ההשגחה וייחוד השם יתעלה ולאהבתו הנכללים בפרשת שמע ואחריהם היתה פרשת והיה אם שמוע להעיר על שכבר יגמול השם יתעלה גמול טוב לאוהבי השם יתעלה ויענוש עונש נפלא לעובדי ע"ז ולזה היו אלו הפרשיות בזה הסדור והנה התועלות בזאת המצות מבואר והוא שיהיה זה לנו לאות שיהיו הדברים האלו על לבנו תמיד לא נשכחם:
@90 **התועלת** השביעי הוא במצות והוא מה שצונו לכתוב אלו הד' פרשיות הנזכרות בסדר הנזכר בתפילין של ראש בד' בתים והתועלת בזאת המצוה הוא שיהיו אלו הדברים לנו לזכרון ולזה הושמו על המוח ששם כח הזוכר והנה היו אלו הפרשיות בתפילין שן ראש בד' בים ובתפילין של יד בבית אחד לסבה שזכרנו בביאורינו לזאת הפרשה והוא כי מזה הצד נתישר אל היות השם יתעלה אחד עם הסתעף ממנו פעולות רבות:
@90 **התועלת** השמיני הוא במצות והוא מה שצונו לכתוב פרשת שמע והיה אם שמוע אצל מזוזת ביתנו כדי להעיר אותנו כי שם ה' נקרא שם ולא יתן המשחית לבא אל בתינו עם שזה יהיה סבה לזכירת אלה הפנות הגדולות אשר צריך שיתנם האדם אל לבו תמיד:
@90 **התועלת** התשיעי הוא במצות והוא מה שצונו ליראה מהשם יתעלה ותועלת זאת המצוה מבואר ממה שזכרנו בביאורנו לזאת המצוה ובכלל הנה היא מישרת להגעת אל השלמות האנושי בתכלית מה שאפשר כמו שבארנו:
@90 **התועלת** העשירי הוא במצות והוא מה שצונו לעבוד השם יתעלה והוא שנבקש מנו הצרכי ותועלת זאת המצוה מבואר כי זה יהיה סבה שנשיג משאלות לבו כי בכל קראנו אליו יענה אם נקרא לו באופן ראוי ויישירנו זה גם כן אל האמונה שכל הטובות הם שפועות מאתו יתע' שהיא מהגדולות שבפנות התוריות והעיוניות:
@90 **התועלת** האחד עשרה הוא במצות והוא מה שצונו להשבע לשמו יתעלה לעת הצורך והנה תועלת זאת המצוה להישיר אל שהשם יתע' הוא אמתי המציאות וקיים ונצחי ולזה תיהיה השבועה בו להורות על אמתת מציאות מה שעליו וקיומו:
@90 **התועלת** השתים עשרה הוא במצות והו' מה שהזהירנו מלנסות את יי' כי זה אולי יביא למעוט אמונה בו כשתקצר יד הנביא מעשות כמו זה המופת:
@90 **התועלת** השלש עשרה הוא במצות והוא מה שצונו להודיע לבנינו ענין עבודתנו במצרים ושהוציאנו משם הש' יתעלה באותות ובמופתי גדולים כשישאלו מה הסבה לאלו העדות והחקים והמשפטים אשר צוה השם יתע' לעשות בפסח או בדבר הבכורות או בשאר מה שצונו השם יתע' שהוא זכר ליציאת מצרים והנה התועלת בה מבואר כי בזה יתפרסמו לו אלו הנפלאות ויתחנך בעבודת השם יתעלה:
@90 **התועלת** הארבע עשרה הוא בדעו' והוא מה שהודיענו כי בשמירת מצות התורה נזכה להצלחה נצחית והיא הצלחת הנפש וימשך לה גם כן הצלחה גופיית והיא הצלחת הגוף וכבר העיר על זה באמרו לטוב לנו כל הימים ולחיותינו כיום הזה:
@90 **התועלת** החמש עשרה הוא במצות והוא מה שהזהירנו מחמול על אחד מז' עממין באמרו לא תכרות להם ברית ולא תחונם והתועלת בזאת האזהרה מבואר שהיא כדי שלא יחטיאו ישראל ויביאום לעבוד ע"ז:
@90 **התועלת** השש עשרה הוא במצות והוא מה שהזהירתנו מהתחתן בעובדי ע"ז ותועלת זאת האזהרה כי זה יהיה סבה אל שיהיה הזרע עובד ע"ז כמו שזכרה התורה:
@90 **התועלת** השבע עשרה הוא במצות והוא מה שצונו לעקור ע"ז מארצינו ולזה אמר מזבחותיהם תתוצון ומצבותיהם תשברון ואשיריהם תגדעון ופסיליהם תשרפון באש:
@90 **התועלת** השמונה עשרה הוא להודיע כי לא בחרבם ירשו ארץ ישראל כי הם המעט מכל העמים אך יהיה להם זה מצד אהבת השם יתעלה אותם שתדבק השגחתו בהם ומפני בריתו עם האבות שהיתה סבה אל שהביא השם יתע' ישראל לעבודתו והיתה זה סבה אל שיהיו ישראל יותר ראוים לירושת הארץ
@90 **התועלת** התשע עשרה הוא להודיע שהטובות אשר ייעד השם יתעלה לטובים ימתין להם העת אשר תהיינה בו יותר טובות ולזה יתכן שימתינם לאלף דור כדי שישים אותם הטובות באופן שלא יסורו אז ובאופן שתהיינה בתכלית מה שאפשר מהשלמו' ואין הענין כן בטובות אשר יביא על הרשעים הראויות לבא להם כי לא יאחרם אך יביאם להם תכף בא העת כדי שיאבדו ברע בבא להם אחר הגעת הטובות ההם להם והנה אמר זה לתת סבה שלהטיב ישראל המתין להם הש יתעלה הגעת הטוב שייעד לאברהם זמן ארוך עד שעדין לא הגיע אל תכליתו כאלו היה זה סבה שלא יכלו ישראל ברעות שהיו ראויות לבא עליהם בעבדם ע"ז כדי שלא תופר בריתו עם האבות ושמר השם יתעלה הגעת הטוב ההוא אל תכליתו אל העת שלא יתכן שיקרה לישראל רע אחריו כי כל האמונות ישובו אז אל האמונה האמתית כמו שאמר הנביא כי אזאהפוך אל עמים שפה ברורה לקרא כלם בשם יי' ולעבדו שכם אחד וכבר התבאר שעדין לא הגיע הטוב ההוא אל תכליתו כי כבר נשבע השם יעת' לאברהם לתת לזרעו ארץ עשר אומות ולא השתדלה התורה עתה לתת לישראל כי אם ארץ ז' אומות ועוד שכבר נאמר בתור' שכאשר ירחיב השם יתעלה את גבולנו נוסיף עוד שלש ערים על שש ערי המקלט וזה דבר לא נהיה עדין לפי מה שהועתק לנו מאלו הקורות בדברי הנביאים וזה לאות כי הרחבת הגבול ההוא יהיה בימי מלך המשיח שאנחנו מקוים יהי רצון שיבא במהרה בימינו והנה הזהירה התורה במקומות רבים מעבוד ע"ז וצותה לשמור מצות התורה למען ירשו ישראל את הארץ ולא יגלו ממנה כי כבר היה נגלת לשם יתעלה שהם ישחיתו אחרי היותם בארץ ויעדו עבודה זרה ויהיה זה סבה להביא עליהם רעות גדולות נפלאות ולזה כפלה להם אלו האזהרות והצווים פעמים רבות כדי להצילם מאלה הרעות לפי מה שאפשר:
